// V-243 step 4f: German story lines of the message log for the later zones and the Spires. Joins the step 3 log catalog
// through registerLog(): the zone texts of Universe 1 from Zone 101 and all zone texts of Universe 2 (getWorldText in
// updates.js; the zone mark "Z:123 " is kept by the mechanism), and the story of the Spires of both universes (getSpireStory,
// rewardSpire1, giveSpireReward, rewardU2Spire and deadInSpire in main.js). Keys are the original English text; patterns and
// the Spire composer see the branded text (Scruffies, renamed enemies), so their pieces are branded when this file loads.
// Names of enemies, maps, Spires, Perks, Heirlooms, Dark Essence, Nullifium, Mutated Seeds and the mutations stay English
// as in the glossary; Floor is Etage, cell is Feld; Corruption, Healthy, Exp and the
// Krit-Chance follow the earlier catalogs. Numbers keep the format of prettify().
// Texts here never contain ASCII double quotes. Not covered: Spire Assault (autoBattle in objects.js), Player Spire
// (playerSpire.js) and the Spire info windows (tooltip in updates.js); they stay English.
var MobileI18nDeStory = (() => {
    const brand = typeof MobileBranding === 'undefined' ? text => text : MobileBranding.text;
    const escape = text => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    // A pattern from English pieces and captures: strings are branded and escaped, N is a number of prettify(), D digits.
    const N = {re: '(\\S+)'}, D = {re: '(\\d+)'};
    const build = (parts, flags) => new RegExp(parts.map(part => typeof part === 'string' ? escape(brand(part)) : part.re).join(''), flags);
    const whole = parts => build([{re: '^'}, ...parts, {re: '$'}]);
    // Zone texts: English of getWorldText → German. Getters with game state have one entry per branch.
    const zones = {
        // Universe 1
        "You stop dead in your tracks. You remember who you came here with, and you remember that you are not happy with Captain Druopitee for bringing you here. You know he landed with you. You know the ship is still here. He's here.":
            "Du bleibst wie angewurzelt stehen. Dir fällt wieder ein, mit wem du hergekommen bist, und auch, dass du Kapitän Druopitee ziemlich übel nimmst, dass er dich hierhergebracht hat. Du weißt, dass er mit dir gelandet ist. Du weißt, dass das Schiff noch hier ist. Er ist hier.",
        "You call a meeting with all of your Trimps to explain the situation. After giving an extremely long, epic, and motivational speech but hearing no reaction from the crowd, you remember that your Trimps cannot understand you. Will you ever learn?":
            "Du rufst alle deine Scruffies zusammen, um ihnen die Lage zu erklären. Nach einer extrem langen, epischen und mitreißenden Rede ohne jede Reaktion der Menge fällt dir ein, dass deine Scruffies dich gar nicht verstehen. Wirst du es je lernen?",
        "How long have you been trapped on this planet? Months? Decades? Travelling through time sure screws up your chronological perception.":
            "Wie lange sitzt du schon auf diesem Planeten fest? Monate? Jahrzehnte? Zeitreisen bringen dein Zeitgefühl ganz schön durcheinander.",
        "Though you have no idea which direction your home planet is, you still believe the ship's GPS could get you home. Maybe Druopitee has the keys. You really want to find him.":
            "Du hast zwar keine Ahnung, in welcher Richtung dein Heimatplanet liegt, glaubst aber immer noch, dass dich das GPS des Schiffs nach Hause bringen könnte. Vielleicht hat Druopitee die Schlüssel. Du willst ihn unbedingt finden.",
        "You just remembered what a taco was. You could really use a taco right now.":
            "Gerade ist dir wieder eingefallen, was ein Taco ist. Einen Taco könntest du jetzt wirklich gebrauchen.",
        "Your stamina is quickly dwindling. Trying to keep up with so many more extra Trimps each Zone is beginning to wear you down. You'll need to practice fighting with stronger, smaller groups to succeed.":
            "Deine Ausdauer schwindet rapide. Mit so vielen zusätzlichen Scruffies in jeder Zone Schritt zu halten, zehrt an deinen Kräften. Du musst lernen, mit stärkeren, kleineren Gruppen zu kämpfen, um Erfolg zu haben.",
        "Woah, you have a lot of Trimps right now. You hadn't really stopped to think about just how many individual Trimps you have directly under your control in a while. Neat!":
            "Wow, du hast gerade richtig viele Scruffies. Du hast schon lange nicht mehr darüber nachgedacht, wie viele einzelne Scruffies direkt unter deinem Befehl stehen. Klasse!",
        "You smell metal and gears, and suddenly feel like you should run a map.":
            "Es riecht nach Metall und Zahnrädern, und plötzlich hast du das Gefühl, du solltest mal wieder eine Map angehen.",
        "You decide to sit down and take a breather, when suddenly a Trimp comes waddle-galloping towards you holding a piece of paper. Hurriedly scrawled on the paper is a drawing of a strange weapon and piece of armor, along with numbers that seem to be dimensional coordinates. You would ask where he found it, but you know better by now.":
            "Du setzt dich gerade hin, um zu verschnaufen, als ein Scruffy mit einem Zettel in der Hand auf dich zugewatschelt-galoppiert kommt. Hastig hingekritzelt sind darauf eine seltsame Waffe und ein Rüstungsteil, dazu Zahlen, die wie Dimensionskoordinaten aussehen. Du würdest ja fragen, wo er das gefunden hat, aber inzwischen weißt du es besser.",
        "You can't stop thinking about where that Trimp found the coordinates for the Slow dimension. Why can't whatever is helping you just come out and help you?":
            "Du musst ständig daran denken, wo dieser Scruffy die Koordinaten der langsamen Dimension gefunden hat. Warum kann das, was dir da hilft, nicht einfach herauskommen und dir helfen?",
        "Ugh, your back is getting sore. It seems like travelling back in time does not reverse the ageing process for the traveller. Bummer.":
            "Uff, dein Rücken tut langsam weh. Offenbar macht eine Zeitreise das Altern des Reisenden nicht rückgängig. Mist.",
        "One of your scientists has informed you that his team was able to successfully create a cure for a non-existent disease. He explains that it's best to be prepared. You sigh heavily.":
            "Einer deiner Forscher teilt dir mit, dass sein Team erfolgreich ein Heilmittel gegen eine Krankheit entwickelt hat, die es nicht gibt. Er erklärt, man sollte eben vorbereitet sein. Du seufzt schwer.",
        "One of your scientists has informed you that an outbreak of a new disease was detected in the laboratory. You go to check on your scientists, and it's quite obvious that they're faking it for attention. You sigh heavily.":
            "Einer deiner Forscher teilt dir mit, dass im Labor eine neue Krankheit ausgebrochen ist. Du siehst nach deinen Forschern, und es ist ziemlich offensichtlich, dass sie nur simulieren, um Aufmerksamkeit zu bekommen. Du seufzt schwer.",
        "You spot another scientist running full speed towards you. He hurriedly informs you that they discovered a new dimension near Zone 35 that is occupied by gigantic Trimps. You sigh heavily.":
            "Schon wieder rennt ein Forscher mit voller Geschwindigkeit auf dich zu. Hastig berichtet er, sie hätten nahe Zone 35 eine neue Dimension entdeckt, in der riesige Scruffies leben. Du seufzt schwer.",
        "Another scientist is coming. You sigh heavily. He says something dumb. You decide to ignore the scientists for a little bit.":
            "Da kommt noch ein Forscher. Du seufzt schwer. Er sagt etwas Dummes. Du beschließt, die Forscher eine Weile zu ignorieren.",
        "It sure is calm and peaceful now. You watch a Falcimp turn a few circles in the sky. You wouldn't mind having wings, but overall you're pretty happy with your species.":
            "Jetzt ist es wirklich ruhig und friedlich. Du siehst einem Falcimp zu, der ein paar Kreise am Himmel dreht. Flügel hättest du schon gern, aber im Großen und Ganzen bist du mit deiner Spezies recht zufrieden.",
        "There's a scientist jumping around trying to get your attention. There's nothing interesting in the sky so you pretend to be fascinated with a rock. The scientist can see you're busy and waits patiently.":
            "Ein Forscher hüpft herum und versucht, deine Aufmerksamkeit zu bekommen. Am Himmel gibt es nichts Interessantes, also tust du so, als wärst du von einem Stein fasziniert. Der Forscher sieht, dass du beschäftigt bist, und wartet geduldig.",
        "Your Scientists are not making it easy to ignore them. You not-so-calmly ask what they want. One of them explains that they discovered a new dimension with lots of extra helium. You'll probably check it out, but you won't tell them that.":
            "Deine Forscher machen es dir nicht leicht, sie zu ignorieren. Nicht ganz so ruhig fragst du, was sie wollen. Einer erklärt, sie hätten eine neue Dimension mit jeder Menge zusätzlichem Helium entdeckt. Du wirst sie dir wahrscheinlich ansehen, aber das sagst du ihnen nicht.",
        "Wow. These structures are getting expensive. There's probably a dimension for that...":
            "Wow. Diese Bauwerke werden langsam teuer. Dafür gibt es bestimmt eine Dimension …",
        "You remember a person from your past. From your old life. There's someone you need to get back to. You'll make it back.":
            "Du erinnerst dich an einen Menschen aus deiner Vergangenheit. Aus deinem alten Leben. Es gibt jemanden, zu dem du zurückmusst. Du wirst es zurück schaffen.",
        "You watch in amazement as a Trimp grabs on to one of those weird tree things and swings around by its arms. These things are getting pretty strong.":
            "Staunend siehst du zu, wie sich ein Scruffy an einem dieser seltsamen Baumdinger festhält und sich an den Armen herumschwingt. Die Kerlchen werden ganz schön stark.",
        "You watch in less amazement as a Trimp tries to take a bite out of a very large rock. These things are not getting much smarter.":
            "Weniger staunend siehst du zu, wie ein Scruffy versucht, in einen sehr großen Stein zu beißen. Viel klüger werden die Kerlchen nicht.",
        "That's quite a sunset. You know once you finally make it out of here, you'll definitely never forget the sights. Unless, of course, you do.":
            "Was für ein Sonnenuntergang. Wenn du hier endlich rauskommst, wirst du diese Anblicke bestimmt nie vergessen. Es sei denn natürlich, du vergisst sie doch.",
        "A small horde of Trimps comes running up towards you, making excited sounding noises. One of them walks to the front of the loud congregation and proudly holds up a boot, slightly larger but the same style as your own. It must be Druopitee's, confirmation that you're heading the right direction. You reward the Trimp who found it with some food and a few pats on the head, then send the boot to the lab to look for any further clues. You wonder why he took his boot off.":
            "Eine kleine Horde Scruffies kommt aufgeregt quiekend auf dich zugerannt. Einer tritt vor die laute Versammlung und hält stolz einen Stiefel hoch, etwas größer als deiner, aber im gleichen Stil. Er muss Druopitee gehören – die Bestätigung, dass du in die richtige Richtung gehst. Du belohnst den Finder mit etwas Nahrung und ein paar Streicheleinheiten und schickst den Stiefel ins Labor, damit dort nach weiteren Hinweisen gesucht wird. Du fragst dich, warum er seinen Stiefel ausgezogen hat.",
        "Your scientists have informed you that half of the boot is now lost in another dimension, thanks to an 'important' test. The results were inconclusive. You ask them to please leave the remaining half in our current dimension, and they look disappointed.":
            "Deine Forscher teilen dir mit, dass die Hälfte des Stiefels dank eines ‚wichtigen‘ Tests nun in einer anderen Dimension verschollen ist. Die Ergebnisse waren nicht eindeutig. Du bittest sie, die übrige Hälfte doch bitte in unserer Dimension zu lassen, und sie sehen enttäuscht aus.",
        "What's this now?! You found a little green piece of metal. Your scientists tell you that it came from a toxic dimension, but that it is also from a dimension rich in helium. They let you know that they can tune your portal to travel to the dimension it originated from, should you want to check it out.":
            "Was ist denn das?! Du hast ein kleines grünes Stück Metall gefunden. Deine Forscher sagen dir, es stamme aus einer giftigen Dimension, die aber auch reich an Helium sei. Sie können dein Portal auf die Dimension einstellen, aus der es stammt, falls du sie dir ansehen willst.",
        "That last Improbability seemed like a nice guy.":
            "Die letzte Oddity wirkte wie ein netter Kerl.",
        "Hopefully spaceships don't rust.":
            "Hoffentlich rosten Raumschiffe nicht.",
        "You reach the top of an incredibly large mountain. You can see at least 50 Zones sprawled out before you. About 30 Zones away, you can see a gigantic spire. It looks like architecture from your home world. You hope it's not a mirage...":
            "Du erreichst den Gipfel eines unglaublich hohen Berges. Mindestens 50 Zonen liegen ausgebreitet vor dir. Etwa 30 Zonen entfernt siehst du eine gigantische Spire. Sie sieht aus wie die Architektur deiner Heimatwelt. Hoffentlich ist das keine Fata Morgana …",
        "Something smells purple. That's probably not good.":
            "Irgendwas riecht lila. Das ist wahrscheinlich nicht gut.",
        "Strange smells continue to swell around you. Judging by changes in wind direction, the smells are coming from the spire. You still can't describe it other than purple.":
            "Um dich herum werden die seltsamen Gerüche immer stärker. Nach den Wechseln der Windrichtung zu urteilen, kommen sie von der Spire. Du kannst sie immer noch nicht anders beschreiben als lila.",
        "Your Trimps seem happy. They're not used to having a purpose, and having one seems to positively affect them! You call a Trimp over and ask him how he's doing, then you remember that he can't talk.":
            "Deine Scruffies wirken glücklich. Sie sind es nicht gewohnt, eine Aufgabe zu haben, und das scheint ihnen richtig gutzutun! Du rufst einen Scruffy zu dir und fragst, wie es ihm geht, dann fällt dir ein, dass er nicht sprechen kann.",
        "You're still not quite sure what that smell is. You feel slightly more powerful, and you fear that your enemies may feel the same way.":
            "Du weißt immer noch nicht genau, was das für ein Geruch ist. Du fühlst dich etwas stärker und fürchtest, dass es deinen Gegnern genauso geht.",
        "After clearing out the previous Zone, you decide to take a day hike to the top of another gigantic mountain to try to find more info about the smell. As you reach the top, your jaw drops. Clear as day, a healthy amount of purple goo is pouring into the atmosphere from the top of the spire. You can see the Zones in front of you beginning to change. This really can't be good.":
            "Nachdem du die letzte Zone geräumt hast, wanderst du auf den Gipfel eines weiteren gigantischen Berges, um mehr über den Geruch herauszufinden. Oben angekommen, fällt dir die Kinnlade herunter. Klar und deutlich ergießt sich eine ordentliche Menge lila Schleim von der Spitze der Spire in die Atmosphäre. Du siehst, wie sich die Zonen vor dir zu verändern beginnen. Das kann wirklich nicht gut sein.",
        "After clearing out the previous Zone, you decide to take a day hike to the top of another gigantic mountain to try to find more info about the smell. As you reach the top, your jaw drops. Clear as day, a healthy amount of purple goo is pouring into the atmosphere from the top of the spire. This must be what's causing all of this Corruption you've been trudging through. The planet seems pretty heavily Corrupted already, you wonder if you're too late.":
            "Nachdem du die letzte Zone geräumt hast, wanderst du auf den Gipfel eines weiteren gigantischen Berges, um mehr über den Geruch herauszufinden. Oben angekommen, fällt dir die Kinnlade herunter. Klar und deutlich ergießt sich eine ordentliche Menge lila Schleim von der Spitze der Spire in die Atmosphäre. Das muss die Ursache all der Corruption sein, durch die du dich schon die ganze Zeit schleppst. Der Planet scheint bereits ziemlich stark von der Corruption befallen zu sein. Du fragst dich, ob du zu spät kommst.",
        "Well, there's not really much doubt about it anymore. Some sort of intelligence is intentionally making life more difficult for you and your Trimps. You take this as a sign that you're pretty important, why else would something risk destroying an entire planet to stop you? Your parents would be so proud.":
            "Tja, daran gibt es eigentlich keinen Zweifel mehr. Irgendeine Intelligenz macht dir und deinen Scruffies absichtlich das Leben schwer. Du nimmst das als Zeichen, dass du ziemlich wichtig bist. Warum sonst würde jemand riskieren, einen ganzen Planeten zu zerstören, nur um dich aufzuhalten? Deine Eltern wären so stolz.",
        "You have trouble putting into words exactly what the Corruption does to the creatures on this planet. They seem to be stripped of all natural abilities and given powers that you didn't know could exist in the primary dimension.":
            "Es fällt dir schwer, in Worte zu fassen, was die Corruption mit den Wesen auf diesem Planeten anstellt. Sie scheinen all ihrer natürlichen Fähigkeiten beraubt und mit Kräften ausgestattet, von denen du nicht wusstest, dass es sie in der primären Dimension geben kann.",
        "None of these corrupted enemies seem to have eyes, so you decide to see if you can get away with flipping one off. As it reacts by roaring and stomping around in a rage, you realize that these things are powerful enough not to need eyes to observe the world. What <i>are</i> these?!":
            "Keiner dieser von der Corruption befallenen Gegner scheint Augen zu haben, also probierst du, ob du einem ungestraft den Mittelfinger zeigen kannst. Als er brüllend und vor Wut stampfend reagiert, wird dir klar, dass diese Dinger mächtig genug sind, um keine Augen zu brauchen. Was <i>sind</i> das für Wesen?!",
        "You awaken from your sleep in a cold sweat to a frantic and terrified noise from the back of the cave where you were sleeping. With urgency, you run to the source of the noise to make sure your Trimps are okay. As you reach the back, you see a handful of Trimps trying to use a small and very angry Snimp as a musical instrument. You put some sand in your ears and go back to sleep.":
            "Du erwachst schweißgebadet von einem panischen, verängstigten Geräusch aus dem hinteren Teil der Höhle, in der du geschlafen hast. Eilig rennst du zur Quelle des Lärms, um nachzusehen, ob es deinen Scruffies gut geht. Hinten angekommen, siehst du eine Handvoll Scruffies, die versuchen, einen kleinen und sehr wütenden Slitherkin als Musikinstrument zu benutzen. Du stopfst dir Sand in die Ohren und schläfst weiter.",
        "The corruption continues to thicken as you near the Spire. You're beginning to grow accustomed to the smell of the Spire, and really don't mind it anymore. It reminds you of blueberries. Evil blueberries.":
            "Je näher du der Spire kommst, desto dichter wird die Corruption. Allmählich gewöhnst du dich an den Geruch der Spire, und er stört dich eigentlich nicht mehr. Er erinnert dich an Blaubeeren. Böse Blaubeeren.",
        "You're so close to the source of corruption that you can taste it, and it doesn't taste good.":
            "Du bist der Quelle der Corruption so nah, dass du sie schmecken kannst, und sie schmeckt nicht gut.",
        "You look back at The Spire and feel kinda bad that there's still a ton of Corruption coming out of it, but you'll get him some time.":
            "Du blickst zurück zur Spire und hast ein etwas schlechtes Gewissen, weil immer noch jede Menge Corruption aus ihr strömt, aber den Kerl kriegst du schon noch.",
        "You don't miss Druopitee too much. You don't remember all that much to miss, but the point stands.":
            "Du vermisst Druopitee nicht besonders. Du erinnerst dich nicht an viel, das man vermissen könnte, aber trotzdem.",
        "It smells extra corrupt. That Spire can't be healthy for the environment.":
            "Es riecht besonders stark nach Corruption. Diese Spire kann nicht gesund für die Umwelt sein.",
        "There's still Corruption, but it feels less threatening. You feel more at peace with the planet and feel like you're on track to repairing it. Surely nothing else terrible will happen any time soon.":
            "Die Corruption ist zwar noch da, aber sie wirkt weniger bedrohlich. Du bist mit dem Planeten mehr im Reinen und hast das Gefühl, auf dem richtigen Weg zu seiner Heilung zu sein. Bestimmt passiert so bald nichts Schlimmes mehr.",
        "Your Trimps seem content. They kinda wish that spire wasn't still pumping purple stuff into their world, but they don't mind too much.":
            "Deine Scruffies wirken zufrieden. Sie wünschten zwar, diese Spire würde nicht immer noch lila Zeug in ihre Welt pumpen, aber es stört sie nicht allzu sehr.",
        "Your Trimps seem content. You taught some basic puppetry to them and they've been putting on some great shows with defeated Snimps.":
            "Deine Scruffies wirken zufrieden. Du hast ihnen ein bisschen Puppenspiel beigebracht, und sie führen mit besiegten Slitherkins tolle Vorstellungen auf.",
        "You wake up in a sweat after a good night's sleep in a cool, dark cave. You dreamt that you were overheating, though that's never really been a problem before. Oh well, strange dreams and memories haven't really indicated anything important before, it's probably nothing.":
            "Nach einer guten Nacht in einer kühlen, dunklen Höhle wachst du schweißgebadet auf. Du hast geträumt, dass du überhitzt, obwohl das noch nie ein Problem war. Na ja, seltsame Träume und Erinnerungen haben bisher nie etwas Wichtiges bedeutet, es ist bestimmt nichts.",
        "It's pretty hot.":
            "Ganz schön heiß hier.",
        "The heat intensifies as you move further and further through the Zones. Instinct says to turn away from the heat, but that wouldn't be any fun.":
            "Die Hitze nimmt zu, je weiter du durch die Zonen ziehst. Dein Instinkt rät dir, dich von der Hitze abzuwenden, aber das wäre ja langweilig.",
        "As you finish clearing out the Zone, you notice a green cloud fall from the sky. It hovers above you for a few moments and shoots some sort of energy at you in a quick, painless burst. Seeming satisfied by the results of this blast, it hurriedly shoots forward a couple of Zones. Before you can even really think about what it could be, ten more green clouds of various sizes appear! They zip down, zap you, then zealously zoom off to the same zone. The clouds look toxic to you, but your Trimps seem to want to follow them.":
            "Als du die Zone geräumt hast, bemerkst du eine grüne Wolke, die vom Himmel fällt. Sie schwebt ein paar Augenblicke über dir und schießt in einem kurzen, schmerzlosen Stoß irgendeine Energie auf dich. Offenbar zufrieden mit dem Ergebnis, saust sie eilig ein paar Zonen voraus. Bevor du überhaupt darüber nachdenken kannst, was das sein könnte, tauchen zehn weitere grüne Wolken in verschiedenen Größen auf! Sie zischen herab, zappen dich und zischen dann zielstrebig zur selben Zone davon. Die Wolken sehen für dich giftig aus, aber deine Scruffies scheinen ihnen folgen zu wollen.",
        "As you climb over a rather large mountain and into the next Zone, you see that the green clouds have finally made it to the ground. Your worries about their toxicity seem to have been needless though, as your Trimps appear to greatly enjoy this rare treat. You watch in amazement as your Trimps begin to grow spines that drip with toxic sludge, and they immediately use their new powers to try to stick each other. You bet they're a bit stronger now.":
            "Als du über einen ziemlich großen Berg in die nächste Zone kletterst, siehst du, dass die grünen Wolken endlich den Boden erreicht haben. Deine Sorge wegen ihrer Giftigkeit war aber anscheinend unbegründet, denn deine Scruffies genießen diesen seltenen Leckerbissen sehr. Staunend siehst du zu, wie deinen Scruffies Stacheln wachsen, von denen giftiger Schlamm tropft, und wie sie ihre neuen Kräfte sofort nutzen, um sich gegenseitig zu piksen. Bestimmt sind sie jetzt etwas stärker.",
        "You and your Trimps have been really enjoying the benefits of what your Scientists call an \"Empowerment of Nature\". However, something up ahead seems to be absorbing all of the Poisonous clouds. Oh no! Your scientists think this will be your last zone with the Poison Empowerment, but they seem convinced that there will be another Empowerment to take its place!":
            "Du und deine Scruffies habt die Vorzüge dessen, was deine Forscher ein ‚Empowerment der Natur‘ nennen, richtig genossen. Doch irgendetwas da vorne scheint alle Giftwolken aufzusaugen. Oh nein! Deine Forscher glauben, dass dies deine letzte Zone mit dem Poison-Empowerment ist, sind aber überzeugt, dass ein anderes Empowerment seinen Platz einnehmen wird!",
        "As you reach the new Zone, you happen to see a Bad Guy finish absorbing the last bit of Poison in the entire Zone, leaving no trace of your new ally, Nature. Before you get too upset about the thought of having to tackle the Magma alone again, Wind floods in to take Poison's place. The spikes on your Trimps stop dripping sludge and begin to spin like propellers, the sound resembling a gigantic swarm of beeimps. These controllable Trimp-generated gusts of wind should be helpful for knocking extra resources into your reach, but you'll still need to deal with that Bad Guy that sucked in all of the Poison...":
            "Als du die neue Zone erreichst, siehst du gerade noch, wie ein Gegner das letzte bisschen Gift in der ganzen Zone aufsaugt, und von deiner neuen Verbündeten, der Natur, bleibt keine Spur. Bevor du dich zu sehr über den Gedanken ärgerst, es wieder allein mit dem Magma aufnehmen zu müssen, strömt Wind herein und nimmt den Platz des Gifts ein. Die Stacheln deiner Scruffies hören auf, Schlamm zu tropfen, und drehen sich wie Propeller; das Geräusch erinnert an einen riesigen Schwarm Beeimps. Diese steuerbaren, von Scruffies erzeugten Windböen sollten dir zusätzliche Ressourcen zuwehen, aber um den Gegner, der das ganze Gift eingesaugt hat, musst du dich trotzdem noch kümmern …",
        "The middle of these Windy Zones are the most beautiful you've seen yet. The Magma and Wind bring all sorts of nutrients and seeds here, leaving the area rich in plant biodiversity. For the first time since you arrived on this planet, you feel truly peaceful. Nature is repairing itself, and you've become one of its tools (but like in a good way).":
            "Die Mitte dieser windigen Zonen ist das Schönste, was du bisher gesehen hast. Magma und Wind tragen allerlei Nährstoffe und Samen hierher, und die Gegend ist reich an Pflanzenvielfalt. Zum ersten Mal, seit du auf diesem Planeten angekommen bist, fühlst du dich wirklich friedlich. Die Natur heilt sich selbst, und du bist eines ihrer Werkzeuge geworden (aber im guten Sinne).",
        "Your Magmamancers have figured out how to make little fountains in the Magma around the base. You like the effect.":
            "Deine Magmamanten haben herausgefunden, wie man im Magma rund um das Lager kleine Springbrunnen anlegt. Dir gefällt der Effekt.",
        "You remember Magmamancers as being pretty cool.":
            "Du erinnerst dich, dass Magmamanten ziemlich cool waren.",
        "Something in the next zone appears to be sucking up all of the Wind again. You've enjoyed all of the extra resources, but you're excited to see what Nature has next for you!":
            "Irgendetwas in der nächsten Zone scheint wieder den ganzen Wind aufzusaugen. Die zusätzlichen Ressourcen waren toll, aber du bist gespannt, was die Natur als Nächstes für dich bereithält!",
        "Once again, a Bad Guy in this Zone has absorbed every trace of your Windy friends. But once again, Nature has replaced them with new, colder ones. Suddenly your Trimps' new spikes stop spinning and start spewing snow! You feel incredibly cold, but your Trimps seem perfectly comfortable. This cold will surely slow down your enemies!":
            "Wieder einmal hat ein Gegner in dieser Zone jede Spur deiner windigen Freunde aufgesogen. Doch wieder einmal hat die Natur sie durch neue, kältere ersetzt. Plötzlich hören die neuen Stacheln deiner Scruffies auf, sich zu drehen, und fangen an, Schnee zu spucken! Dir ist unglaublich kalt, aber deine Scruffies fühlen sich pudelwohl. Diese Kälte wird deine Gegner bestimmt verlangsamen!",
        "While the Windy Zones were beautiful, the Ice Zones are nearly indescribable. Deep blues from the frozen ground contrast sharply with the fiery reds of the Magma rivers, and these two systems have equalized at a very comfortable ambient temperature. Your Trimps are too cold to touch though, your hand is still stuck to the one you high-fived at the start of the last zone.":
            "Die windigen Zonen waren schön, aber die Eiszonen sind kaum zu beschreiben. Das tiefe Blau des gefrorenen Bodens hebt sich scharf vom feurigen Rot der Magmaflüsse ab, und beide haben sich auf eine sehr angenehme Umgebungstemperatur eingependelt. Anfassen kann man deine Scruffies aber nicht, sie sind zu kalt: Deine Hand klebt immer noch an dem, mit dem du am Anfang der letzten Zone abgeklatscht hast.",
        "Right on cue, another enemy has absorbed the Empowerment of Ice, and Nature has reacted by refilling the Zone with familiar green clouds. Poison is back! Your Trimps' spikes resume spewing toxic sludge, and finally the Trimp stuck to your hand warms up enough to fall off. No more high-fiving Trimps in the Ice Zones.":
            "Pünktlich wie bestellt hat ein weiterer Gegner das Empowerment des Eises aufgesogen, und die Natur füllt die Zone wieder mit vertrauten grünen Wolken. Das Gift ist zurück! Die Stacheln deiner Scruffies spucken wieder giftigen Schlamm, und endlich taut der Scruffy an deiner Hand genug auf, um abzufallen. Nie wieder Abklatschen mit Scruffies in den Eiszonen.",
        "The Magma continues to sap your Trimps' strength as you press through the Zones, but they seem to be adapting well in spirits. It seems like each generation likes the heat more and more.":
            "Das Magma zehrt weiter an der Kraft deiner Scruffies, während du dich durch die Zonen kämpfst, aber ihre Stimmung scheint sich gut anzupassen. Jede Generation scheint die Hitze mehr zu mögen.",
        "You're detecting a pattern here! Poison has once again given way to Wind, and you have a feeling that this Wind will soon give way to Ice. The Bad Guys can absorb as much Nature as they want! Their Tokens will only help you to strengthen Nature, and Nature will always be back. With your new ally, you can totally handle the Magma.":
            "Hier zeichnet sich ein Muster ab! Das Gift ist wieder dem Wind gewichen, und du ahnst, dass dieser Wind bald dem Eis weichen wird. Die Gegner können so viel Natur aufsaugen, wie sie wollen! Ihre Tokens helfen dir nur, die Natur zu stärken, und die Natur kommt immer zurück. Mit deiner neuen Verbündeten wirst du mit dem Magma locker fertig.",
        "You asked that Omnipotrimp nicely not to explode after you killed it, but it exploded anyways. Pretty rude.":
            "Du hast diesen Crownmaw nett gebeten, nicht zu explodieren, nachdem du ihn erledigt hast, aber er ist trotzdem explodiert. Ganz schön unhöflich.",
        "Good job not high-fiving any Trimps so far this time. You are worried morale might fall if you spend too much time with such a difficult restriction, but you're pretty sure Poison is coming up soon.":
            "Gut gemacht, bisher hast du diesmal mit keinem Scruffy abgeklatscht. Du machst dir Sorgen, dass die Moral leidet, wenn du zu lange mit einer so harten Einschränkung lebst, aber du bist ziemlich sicher, dass bald das Gift kommt.",
        "You're determined to repair the planet, and now that Nature is on your side you feel it might actually be possible. Either way, you know you must be doing something right to have earned the loyalty of Trimps and Nature.":
            "Du bist fest entschlossen, den Planeten zu heilen, und jetzt, da die Natur auf deiner Seite ist, scheint das tatsächlich möglich. So oder so musst du etwas richtig machen, wenn du dir die Treue der Scruffies und der Natur verdient hast.",
        "This planet is really freaking big. You feel like you've been walking around it for years and still haven't seen everything there is to offer. Shouldn't there be another spire around here or something?":
            "Dieser Planet ist echt verdammt groß. Du hast das Gefühl, schon seit Jahren um ihn herumzulaufen, und hast immer noch nicht alles gesehen, was er zu bieten hat. Müsste hier nicht irgendwo noch eine Spire stehen?",
        "It's starting to smell purple again. You must be getting close to another spire.":
            "Es riecht langsam wieder lila. Du musst einer weiteren Spire nahe sein.",
        "You can finally see it, clear as day. No more than 15 Zones in the distance stands a giant spire, even more menacing than the first. A loud, echoing voice booms from the tower, matching the tone and cadence of Druopitee himself. It's a little far away to hear perfectly, but it sounds like he's asking you nicely to please leave him be.":
            "Endlich siehst du sie, klar und deutlich. Keine 15 Zonen entfernt steht eine gigantische Spire, noch bedrohlicher als die erste. Eine laute, hallende Stimme dröhnt aus dem Turm, mit genau dem Tonfall und Rhythmus von Druopitee selbst. Sie ist etwas zu weit weg, um alles zu verstehen, aber es klingt, als bitte er dich höflich, ihn doch bitte in Ruhe zu lassen.",
        "Something feels wrong, but you can't quite figure out what. You eventually find a pebble in your shoe and everything seems much better!":
            "Irgendetwas fühlt sich falsch an, aber du kommst nicht darauf, was. Schließlich findest du einen Kiesel in deinem Schuh, und alles scheint viel besser!",
        "You hear the voice again, and can tell there's definitely something weird about it - as if it was coming from a ghost or something. Though you suppose that makes sense, since you've already killed Druopitee.":
            "Du hörst die Stimme wieder und merkst, dass definitiv etwas Seltsames an ihr ist, als käme sie von einem Geist oder so. Das ergibt wohl Sinn, schließlich hast du Druopitee ja schon getötet.",
        "You hear something rustling in a bush and get totally psyched up for something new and exciting. As you walk cautiously towards the bush, a Rabbimp quickly runs out and away.":
            "Du hörst etwas in einem Busch rascheln und freust dich riesig auf etwas Neues und Aufregendes. Als du vorsichtig auf den Busch zugehst, flitzt ein Rabbimp heraus und davon.",
        "As you get closer and closer to the spire, the voice gets clearer and clearer. You can pick up notes of terror from whatever being is up there, as if he wants to just be left alone to destroy the world. You don't feel much sympathy though.":
            "Je näher du der Spire kommst, desto klarer wird die Stimme. Du hörst eine Spur Angst bei dem Wesen dort oben heraus, als wolle es einfach in Ruhe gelassen werden, um die Welt zu zerstören. Viel Mitgefühl hast du allerdings nicht.",
        "You trip over a rock and stumble a bit, but fix your footing before totally falling over. You glance around and it doesn't seem like any of the Trimps noticed!":
            "Du stolperst über einen Stein und gerätst ins Straucheln, fängst dich aber, bevor du ganz hinfällst. Du schaust dich um, und es sieht nicht so aus, als hätte einer der Scruffies etwas bemerkt!",
        "You're now so close to this new spire that you can taste it, literally. These things are gross.":
            "Du bist dieser neuen Spire jetzt so nah, dass du sie schmecken kannst, buchstäblich. Diese Dinger sind eklig.",
        "You wonder if you could get your scientists to invent chewing gum...":
            "Du fragst dich, ob deine Forscher wohl Kaugummi erfinden könnten …",
        "The deranged spirit in the tower is now begging that you stay back. It obviously knows you destroyed the last tower and doesn't want you taking out another. Too bad, buddy. You're coming.":
            "Der wahnsinnige Geist im Turm fleht dich nun an, wegzubleiben. Er weiß offensichtlich, dass du den letzten Turm zerstört hast, und will nicht, dass du noch einen erledigst. Pech gehabt, Kumpel. Du kommst.",
        "A voice in the back of your mind tells you there should be something big soon, but you see nothing. Oh well.":
            "Eine Stimme in deinem Hinterkopf sagt dir, dass bald etwas Großes kommen müsste, aber du siehst nichts. Na ja.",
        "You're glad you have Fluffy around now. He seems to be getting along well with the other Trimps, and seems happy to have found others like him. He doesn't seem to be any smarter than a normal Trimp so you're sure you'll get some entertainment out of him.":
            "Du bist froh, dass Fluffy jetzt bei dir ist. Er scheint sich gut mit den anderen Scruffies zu verstehen und freut sich offenbar, andere wie ihn gefunden zu haben. Klüger als ein normaler Scruffy scheint er nicht zu sein, also wirst du mit ihm bestimmt deinen Spaß haben.",
        "You wish you had a pet.":
            "Du wünschtest, du hättest ein Haustier.",
        "These healthy spots of land seem to be increasing as the Spire pumps more and more into the air! Hopefully that's a good thing. You ask Fluffy what he thinks and he nods in approval.":
            "Diese gesunden Flecken Land scheinen sich auszubreiten, je mehr die Spire in die Luft pumpt! Hoffentlich ist das etwas Gutes. Du fragst Fluffy, was er davon hält, und er nickt zustimmend.",
        "Geeze, this Corruption is starting to look pretty nasty. Those Spires need to fall soon...":
            "Meine Güte, diese Corruption sieht langsam ziemlich übel aus. Diese Spires müssen bald fallen …",
        "Watch your step, there's some Magma on the ground over there.":
            "Pass auf, wo du hintrittst, da drüben ist Magma auf dem Boden.",
        "If Druopitee has really immortalized himself in an infinite amount of Spires, you might be here for a while.":
            "Wenn Druopitee sich wirklich in unendlich vielen Spires verewigt hat, bist du womöglich eine ganze Weile hier.",
        "You attempt to put Fluffy through your rigorous Scientist training program, but he doesn't want to. He wouldn't have any trouble, but he doesn't want the label. You still couldn't be happier to have the little guy around!":
            "Du versuchst, Fluffy durch dein strenges Ausbildungsprogramm für Forscher zu schicken, aber er will nicht. Er hätte keinerlei Probleme damit, er will nur das Etikett nicht. Trotzdem könntest du nicht glücklicher sein, den kleinen Kerl um dich zu haben!",
        "You really feel like something is missing from your life. Everything feels hollow and sad.":
            "Du hast wirklich das Gefühl, dass dir etwas im Leben fehlt. Alles fühlt sich hohl und traurig an.",
        "Should be coming up on another Spire Zone soon. You stop and sit beside a beautiful Magma river and wonder what kinds of crazy stuff could be waiting for you up there. Then you realize it's probably just another Spire, so you get up and keep moving.":
            "Bald müsste die nächste Spire-Zone kommen. Du setzt dich an einen wunderschönen Magmafluss und fragst dich, was für verrücktes Zeug dort oben auf dich warten könnte. Dann wird dir klar, dass es wahrscheinlich einfach wieder eine Spire ist, also stehst du auf und gehst weiter.",
        "Some familiar Spirish odors begin hitting your nostrils again and you sneeze, hilariously startling a few billion Trimps. Never gets old.":
            "Vertraute Spire-Gerüche steigen dir wieder in die Nase, und du niest, was ein paar Milliarden Scruffies urkomisch erschreckt. Wird nie langweilig.",
        "You can finally see the next Spire in the distance, a thick purple cloud boiling out of the top. Hard to believe there's an infinite amount of these things, how big even is this planet?":
            "Endlich siehst du in der Ferne die nächste Spire, aus deren Spitze eine dicke lila Wolke quillt. Kaum zu glauben, dass es unendlich viele dieser Dinger gibt. Wie groß ist dieser Planet eigentlich?",
        "Weird, you feel like you should be able to see the next Spire by now, but it's not there. Maybe you should have checked the other Spires a bit more thoroughly.":
            "Seltsam, eigentlich müsstest du die nächste Spire inzwischen sehen, aber sie ist nicht da. Vielleicht hättest du die anderen Spires etwas gründlicher untersuchen sollen.",
        "Ahh, that gross old taste of Spire. You'll never get used to that. Most of your Trimps are trying to stay under trees, but Fluffy is running around with his tongue out as if he was trying to catch snowflakes.":
            "Ah, dieser eklige alte Spire-Geschmack. Daran wirst du dich nie gewöhnen. Die meisten deiner Scruffies versuchen, unter Bäumen zu bleiben, aber Fluffy rennt mit herausgestreckter Zunge herum, als wolle er Schneeflocken fangen.",
        "Did you leave the oven on? Oh yeah, you don't have an oven. Now you wonder what an oven even is. Oh well.":
            "Hast du den Ofen angelassen? Ach ja, du hast ja gar keinen Ofen. Jetzt fragst du dich, was ein Ofen überhaupt ist. Na ja.",
        "It really seemed like you weakened Druopitee back there. Maybe you'll be able to at least shut off any last conscious parts of him with just one more Spire?":
            "Es sah wirklich so aus, als hättest du Druopitee dort hinten geschwächt. Vielleicht kannst du mit nur einer weiteren Spire wenigstens die letzten bewussten Teile von ihm abschalten?",
        "You can't shake the feeling like you forgot to do something.":
            "Du wirst das Gefühl nicht los, etwas vergessen zu haben.",
        "The Healthy mutation is starting to spread nicely now. The Bad Guys hurt quite a bit more, but you're pretty sure you're doing the right thing which kinda makes you feel good.":
            "Die Healthy-Mutation breitet sich jetzt schön aus. Die Gegner schlagen zwar deutlich härter zu, aber du bist ziemlich sicher, das Richtige zu tun, und das fühlt sich irgendwie gut an.",
        "It seems like the Healthy mutation has stopped spreading. That's alright though, some other version of you will probably take care of it.":
            "Die Healthy-Mutation scheint sich nicht mehr auszubreiten. Ist aber in Ordnung, irgendeine andere Version von dir kümmert sich bestimmt darum.",
        "The land sure looks terrible and corrupted, but at least you have Fluffy.":
            "Das Land sieht zwar schrecklich und von der Corruption zerfressen aus, aber immerhin hast du Fluffy.",
        "What do you have against Fluffy?":
            "Was hast du denn gegen Fluffy?",
        "The Trimps tried tying two Turkimps to this tall tree, then the Turkimps thrashed those three trillion Trimps, throwing the Trimps tumbling towards the tall tree. The Trimps truly tried. Those Turkimps though... they tough.":
            "Die Scruffies versuchten, zwei Gobblebies an diese große Tanne zu binden, dann trampelten die Gobblebies die drei Billionen Scruffies nieder und schleuderten sie taumelnd gegen die große Tanne. Die Scruffies taten wirklich, was sie konnten. Aber diese Gobblebies … total taff.",
        "Wow, you've gotten pretty far. You would have never guessed there'd be this many Zones out there, but here you are.":
            "Wow, du bist ganz schön weit gekommen. Du hättest nie gedacht, dass es dort draußen so viele Zonen gibt, aber hier bist du.",
        "It's just about time for another Spire, don't you think?":
            "Langsam wird es Zeit für die nächste Spire, findest du nicht?",
        "This part of the world seems to be at a much higher elevation than any other part that you've been at. The air is strangely clear, and you can see more of the planet sprawled out around you than ever before. It feels good to see everything you're fighting for and feel like it's worth it.":
            "Dieser Teil der Welt scheint viel höher zu liegen als alle, in denen du bisher warst. Die Luft ist seltsam klar, und du siehst mehr vom Planeten um dich herum als je zuvor. Es tut gut, alles zu sehen, wofür du kämpfst, und zu spüren, dass es sich lohnt.",
        "This part of the world seems to be at a really low elevation, and lots of Corruption is building up in it. Gross.":
            "Dieser Teil der Welt scheint richtig tief zu liegen, und hier sammelt sich jede Menge Corruption. Eklig.",
        "Once again, you can taste the Spire, it must just be over that next hill now. Fluffy seems excited.":
            "Wieder einmal kannst du die Spire schmecken, sie muss gleich hinter dem nächsten Hügel liegen. Fluffy wirkt aufgeregt.",
        "Hey! Is that... oh, nope, just some dirt.":
            "He! Ist das … ach nein, nur etwas Dreck.",
        "It's time. He's weak. You've got this. Time to make this planet Healthy again.":
            "Es ist so weit. Er ist schwach. Du schaffst das. Zeit, diesen Planeten wieder gesund zu machen.",
        "You're feeling rather itchy today. You ask some Trimps to scratch your back but they don't really want to.":
            "Heute juckt es dich ziemlich. Du bittest ein paar Scruffies, dir den Rücken zu kratzen, aber sie haben keine rechte Lust.",
        "Well you've totally 100% eradicated Druopitee's consciousness, now you figure it's just time to clear the rest of his brainless Echoes out of the remaining Spires.":
            "Tja, Druopitees Bewusstsein ist jetzt zu 100% ausgelöscht. Jetzt ist es wohl Zeit, seine hirnlosen Echos aus den übrigen Spires zu räumen.",
        "Druopitee is just over there getting stronger, someone should really do something about him.":
            "Druopitee wird da drüben immer stärker. Jemand sollte wirklich etwas gegen ihn unternehmen.",
        "Fluffy seemed to greatly enjoy downing that last Spire, he strongly dislikes those Echoes of Druopitee. Nobody sticks Fluffy in a cage and gets away with it!":
            "Fluffy hatte offenbar großen Spaß daran, die letzte Spire zu Fall zu bringen; er kann diese Echos von Druopitee überhaupt nicht leiden. Niemand steckt Fluffy in einen Käfig und kommt damit durch!",
        "Fluffy tried to eat some Nature Tokens to gain their power but to no avail. You assure him that you already think he's pretty grand, but he is determined to get stronger. You feel like there's something big in his future...":
            "Fluffy hat versucht, ein paar Nature Tokens zu fressen, um ihre Kraft zu bekommen, aber vergeblich. Du versicherst ihm, dass du ihn schon jetzt ziemlich großartig findest, aber er ist fest entschlossen, stärker zu werden. Du hast das Gefühl, dass ihm etwas Großes bevorsteht …",
        "The planet looks pretty charred. Fluffy looks proud of something but you're not sure what.":
            "Der Planet sieht ziemlich verkohlt aus. Fluffy wirkt auf irgendetwas stolz, aber du weißt nicht genau, worauf.",
        "You feel like there is supposed to be something here that isn't. You wonder if you had something to do with that.":
            "Du hast das Gefühl, dass hier etwas sein sollte, das nicht da ist. Du fragst dich, ob du etwas damit zu tun hattest.",
        "You finish climbing down the Spire with Fluffy. With the last Spire cleared of Druopitee's echoes, maybe this world can finally start to heal. Unfortunately, this isn't the only Universe where Druopitee has wreaked havoc! You still have some work ahead of you to clean up this mess he made.":
            "Gemeinsam mit Fluffy kletterst du die Spire hinunter. Jetzt, da die letzte Spire von Druopitees Echos befreit ist, kann diese Welt vielleicht endlich heilen. Leider ist das nicht das einzige Universum, in dem Druopitee Chaos gestiftet hat! Du hast noch einiges zu tun, um das Durcheinander zu beseitigen, das er angerichtet hat.",
        "That Spire itself might be a husk of what it once was, but those Bad Guys inside are tough! Fluffy seems disappointed, but you'll get that Echo next time!":
            "Die Spire selbst mag nur noch eine Hülle dessen sein, was sie einmal war, aber die Gegner darin sind zäh! Fluffy wirkt enttäuscht, aber das Echo kriegst du nächstes Mal!",
        // Universe 2
        "\"A journey of 1000 Zones begins with a single Zone.\" - Probably someone":
            "‚Eine Reise von 1000 Zonen beginnt mit einer einzigen Zone.‘ – Vermutlich irgendwer",
        "While this Universe seems very similar to the one you were just in, it feels quite a bit different. You can't quite figure out what exactly is different, but it totally is.":
            "Dieses Universum scheint dem, aus dem du gerade kommst, sehr ähnlich zu sein, und fühlt sich doch ganz anders an. Du kommst nicht genau darauf, was anders ist, aber es ist definitiv anders.",
        "You feel like you've climbed through these Zones thousands of times, but you can only clearly remember one time that felt like ages ago in a different Universe. You feel weird.":
            "Du hast das Gefühl, schon tausende Male durch diese Zonen geklettert zu sein, aber klar erinnern kannst du dich nur an ein einziges Mal, das sich anfühlt, als sei es Ewigkeiten her, in einem anderen Universum. Du fühlst dich seltsam.",
        "But have you been to this Universe before? You're really not quite sure. Every day that passes here makes your memories feel like another lifetime ago.":
            "Aber warst du schon einmal in diesem Universum? Du bist dir wirklich nicht sicher. Mit jedem Tag hier fühlen sich deine Erinnerungen mehr an wie aus einem anderen Leben.",
        "You decide to tell the story of your travels to your Trimps, so that someone will remember if your memory continues to get worse. You tell them about the massive armies, the Spires, Druopitee, Nature, and everything else you can think of. The Trimps seem excited by the tale, but they can't talk.":
            "Du beschließt, deinen Scruffies die Geschichte deiner Reisen zu erzählen, damit sich jemand erinnert, falls dein Gedächtnis noch schlechter wird. Du erzählst von den gewaltigen Armeen, den Spires, Druopitee, der Natur und allem anderen, was dir einfällt. Die Scruffies scheinen von der Geschichte begeistert, aber sprechen können sie nicht.",
        "Scruffy runs up to inform you that you could run a regular map to find directions to something called \"Big Wall\". You remember a wall from before, but you don't remember finding it so soon. What else is going to be different?":
            "Scruffy kommt angerannt und teilt dir mit, dass du in einer normalen Map den Weg zu etwas namens ‚Big Wall‘ finden könntest. Du erinnerst dich an eine Mauer von früher, aber nicht daran, sie so früh gefunden zu haben. Was wird wohl noch anders sein?",
        "At your request, your Scientists are running tests to try and identify further differences between your original Universe and this one. Unfortunately, they don't know anything about your old Universe and probably won't be able to spot any differences.":
            "Auf deine Bitte führen deine Forscher Tests durch, um weitere Unterschiede zwischen deinem ursprünglichen Universum und diesem zu finden. Leider wissen sie nichts über dein altes Universum und werden wohl keine Unterschiede erkennen.",
        "One thing you remember for sure about the last Universe is that you found a Portal device at the twentieth zone. However here, your Scientists have detected a massive portalesque energy reading on only the fifteenth Zone. Interesting.":
            "Eines weißt du aus dem letzten Universum ganz sicher: Das Portal-Gerät hast du in der zwanzigsten Zone gefunden. Hier haben deine Forscher aber schon in der fünfzehnten Zone eine gewaltige, portalartige Energiesignatur gemessen. Interessant.",
        "You decide to try and stock up on some Helium in preparation for the supposed Portal device that you're quickly approaching. You ask a Scientist where you could find some and he scurries under a table. A more stoic Scientist informs you that Helium is incredibly volatile in this universe and that almost none can be found. That might throw a wrench in your plans...":
            "Du beschließt, dich für das angebliche Portal-Gerät, dem du dich schnell näherst, mit etwas Helium einzudecken. Du fragst einen Forscher, wo du welches finden könntest, und er huscht unter einen Tisch. Ein gefassterer Forscher erklärt dir, dass Helium in diesem Universum unglaublich flüchtig ist und fast keines zu finden ist. Das könnte deine Pläne durchkreuzen …",
        "Apparently a few elements have different properties here than back in the last Universe. Either that or the Trimps currently bathing in mercury are going to have a rough future.":
            "Offenbar haben hier ein paar Elemente andere Eigenschaften als im letzten Universum. Entweder das, oder den Scruffies, die gerade in Quecksilber baden, steht eine harte Zukunft bevor.",
        "You start to feel angry as you get closer to the fifteenth Zone. You're not sure if it's due to the energy your scientists detected, or the Trimps that keep throwing berries at your head. But one of them is definitely making you angry.":
            "Je näher du der fünfzehnten Zone kommst, desto wütender wirst du. Du weißt nicht, ob es an der Energie liegt, die deine Forscher gemessen haben, oder an den Scruffies, die dir ständig Beeren an den Kopf werfen. Aber eins von beiden macht dich definitiv wütend.",
        "Scruffy informs you that there is one particular element regarded as king here, Radon. While highly volatile in your home Universe, it's a stable gas here with tremendous potential for power generation.":
            "Scruffy erklärt dir, dass hier ein bestimmtes Element als König gilt: Radon. In deinem Heimatuniversum hoch flüchtig, ist es hier ein stabiles Gas mit enormem Potenzial zur Energiegewinnung.",
        "You ask Scruffy for more information on Radon, and he sits you down to tell you a story. He informs you that you're not the first human to come to their planet, that someone had been here 500 years ago who caused great harm to the planet. He set up giant Spires all around the World that harvested Radon from the atmosphere and beamed the power to a different Universe. You have a feeling that you know which Universe received this power, and you're starting to have a good idea of why Fluffy picked this particular Universe to send you to.":
            "Du bittest Scruffy um mehr Informationen über Radon, und er setzt sich mit dir hin, um dir eine Geschichte zu erzählen. Du bist nicht der erste Mensch auf ihrem Planeten, sagt er: Schon vor 500 Jahren war jemand hier, der dem Planeten großen Schaden zugefügt hat. Er errichtete überall auf der Welt riesige Spires, die Radon aus der Atmosphäre gewannen und die Energie in ein anderes Universum strahlten. Du ahnst, welches Universum diese Energie empfangen hat, und langsam wird dir klar, warum Fluffy ausgerechnet dieses Universum ausgesucht hat, um dich hierherzuschicken.",
        "There is a device of great evil here. See if you can take it for yourself!":
            "Hier gibt es ein Gerät von großer Bosheit. Versuch, es dir zu holen!",
        "Holy cowimp, there's an Improbability at the end of this Zone! But the planet doesn't look broken, this is... improbable...":
            "Heiliger Bimbam, am Ende dieser Zone ist eine Oddity! Aber der Planet sieht gar nicht zerbrochen aus. Das ist … unwahrscheinlich …",
        "Your Scientists have confirmed that the Spires are indeed still active on this planet, but are incredibly far away in lands your Trimps are nowhere near powerful enough to survive in.":
            "Deine Forscher haben bestätigt, dass die Spires auf diesem Planeten tatsächlich noch aktiv sind, aber unglaublich weit weg, in Ländern, in denen deine Scruffies bei Weitem nicht stark genug sind, um zu überleben.",
        "Knowing that Druopitee is in your Universe, you ask Scruffy who is manning the Spires. He hangs his head in shame and lets you know that there are 5 Trimps, previously friends of Scruffy's, that were enticed by Druopitee's magic. He doesn't seem to want to talk much more about it.":
            "Da du weißt, dass Druopitee in deinem Universum ist, fragst du Scruffy, wer die Spires besetzt. Beschämt lässt er den Kopf hängen und erzählt dir von 5 Scruffies, früher seine Freunde, die Druopitees Magie verfallen sind. Viel mehr will er darüber anscheinend nicht sagen.",
        "Your Trimps catch a bird and build a little home for it, but it flies away.":
            "Deine Scruffies fangen einen Vogel und bauen ihm ein kleines Zuhause, aber er fliegt davon.",
        "Your memories of the last Universe are fading and you have no idea how many times you've been here in this Universe. This could be your first or thousandth time here. Neat!":
            "Deine Erinnerungen an das letzte Universum verblassen, und du hast keine Ahnung, wie oft du schon in diesem Universum warst. Das könnte dein erstes oder dein tausendstes Mal sein. Klasse!",
        "You're not sure how much more beautiful this Universe is than the last one, but it's hard not to stop and take in all the scenery every once in a while. Sprawling hills and flowing rivers in every direction make it almost worth the frankly ridiculous amount of enemies hiding everywhere.":
            "Du weißt nicht genau, um wie viel schöner dieses Universum ist als das letzte, aber es fällt schwer, nicht ab und zu stehen zu bleiben und die Landschaft zu genießen. Weite Hügel und fließende Flüsse in jeder Richtung machen die ehrlich gesagt lächerliche Menge an Gegnern, die sich überall verstecken, fast wieder wett.",
        "You deserve hazard pay or something.":
            "Du verdienst eine Gefahrenzulage oder so.",
        "One of your regular Trimps seems to have picked up the ability to speak a few words from Scruffy. They're too dirty to repeat though.":
            "Einer deiner normalen Scruffies scheint von Scruffy ein paar Wörter aufgeschnappt zu haben. Die sind allerdings zu unanständig, um sie zu wiederholen.",
        "As you reach the top of another in this seemingly infinite sea of hills, you notice a tiny tablet. It's written in some language you've never seen, so you figure you'll hold on to it and see if Scruffy can translate.":
            "Als du den Gipfel eines weiteren Hügels in diesem scheinbar endlosen Hügelmeer erreichst, bemerkst du eine winzige Tafel. Sie ist in einer Sprache geschrieben, die du noch nie gesehen hast, also behältst du sie, um zu sehen, ob Scruffy sie übersetzen kann.",
        "Scruffy seems to be avoiding you ever since you found the tablet. You're not like... 100% positive but you're pretty sure.":
            "Seit du die Tafel gefunden hast, scheint Scruffy dir aus dem Weg zu gehen. Du bist dir nicht … 100% sicher, aber ziemlich.",
        "You finally catch Scruffy while he's eating and ask him about the tablet. He tells you it's not a big deal, but that him and his six friends were all given some \"enhancements\" by Druopitee 500 years ago. Together they helped carry out Druopitee's bidding, setting up seven different Spires, harvesting Radon, and beaming the Power away. Scruffy lets you know that Fluffy and himself eventually realized how much damage Druopitee was causing to their planet and rebelled against Druopitee and the other Five. This tablet was an order from Druopitee to apprehend them.":
            "Endlich erwischst du Scruffy beim Essen und fragst ihn nach der Tafel. Er sagt, das sei keine große Sache, aber er und seine sechs Freunde hätten vor 500 Jahren von Druopitee ein paar ‚Verbesserungen‘ bekommen. Gemeinsam halfen sie, Druopitees Befehle auszuführen: Sie errichteten sieben verschiedene Spires, gewannen Radon und strahlten die Energie fort. Scruffy erzählt dir, dass Fluffy und er irgendwann erkannten, welchen Schaden Druopitee ihrem Planeten zufügte, und sich gegen Druopitee und die anderen fünf auflehnten. Diese Tafel war Druopitees Befehl, sie festzunehmen.",
        "You just realized... you thought you named Fluffy Fluffy. That sneaky telepathic Trimp!":
            "Gerade ist es dir klar geworden … Du dachtest, du hättest Fluffy Fluffy getauft. Dieser hinterlistige telepathische Scruffy!",
        "You haven't seen Scruffy around the town much since your last conversation. Telling stories about his old friends seems to be painful for him, though you'd expect him to have moved through the grief stages after 500 years.":
            "Seit eurem letzten Gespräch hast du Scruffy kaum noch in der Stadt gesehen. Von seinen alten Freunden zu erzählen, scheint ihm wehzutun, auch wenn man meinen könnte, dass er die Phasen der Trauer nach 500 Jahren hinter sich hat.",
        "You ask Scruffy why he's so conversational and Fluffy is not. Scruffy shows you a whole trove of books that Druopitee had left behind, that Scruffy had been reading for the past 500 years. You figure Fluffy spent most of that 500 years stuck in a time loop.":
            "Du fragst Scruffy, warum er so gesprächig ist und Fluffy nicht. Scruffy zeigt dir einen ganzen Schatz an Büchern, die Druopitee zurückgelassen hat und die Scruffy in den letzten 500 Jahren gelesen hat. Fluffy hat diese 500 Jahre wohl größtenteils in einer Zeitschleife festgesteckt.",
        "A Trimp eats a rock.":
            "Ein Scruffy isst einen Stein.",
        "You wonder how Fluffy ended up in your Universe if he started out here. You'll ask Scruffy about it when he quits being all sulky.":
            "Du fragst dich, wie Fluffy in deinem Universum gelandet ist, wenn er ursprünglich von hier stammt. Du wirst Scruffy danach fragen, sobald er aufhört zu schmollen.",
        "Today, you held the first annual Trimp Toss. It was a pretty nice day.":
            "Heute hast du den ersten jährlichen Scruffy-Weitwurf veranstaltet. Es war ein ziemlich schöner Tag.",
        "This zone is really freaking hot.":
            "Diese Zone ist echt verdammt heiß.",
        "You catch Scruffy helping a group of small Trimps across a river. What a cool dude.":
            "Du ertappst Scruffy dabei, wie er einer Gruppe kleiner Scruffies über einen Fluss hilft. Was für ein cooler Typ.",
        "A few of your Trimps are getting whiny so you take them for a walk. Seemed to do the trick, they just needed to burn some energy and pee.":
            "Ein paar deiner Scruffies werden quengelig, also machst du einen Spaziergang mit ihnen. Hat geholfen: Sie mussten nur etwas Energie loswerden und pinkeln.",
        "Scruffy is finally in a good mood and seems quite a bit stronger than before, so you figure now is a good time to ask him about Fluffy. In exchange for his good mood, he agrees to tell you the rest of the story. According to him, Fluffy was stationed at the second Spire while Scruffy was at the third. Fluffy and Scruffy each destroyed their own Spires, but Fluffy was caught by Druopitee and took the fall for both of them. Druopitee left the six remaining enhanced Trimps to take care of the remaining five Spires, and took Fluffy with him. You ask what the names of the other five Trimps are and he tells you: Huffy, Stuffy, Buffy, Tuffy, and Puffy.":
            "Scruffy ist endlich gut gelaunt und scheint deutlich stärker als vorher, also hältst du den Moment für günstig, ihn nach Fluffy zu fragen. Seiner guten Laune zuliebe erzählt er dir den Rest der Geschichte. Ihm zufolge war Fluffy an der zweiten Spire stationiert und Scruffy an der dritten. Fluffy und Scruffy zerstörten jeweils ihre eigene Spire, aber Fluffy wurde von Druopitee erwischt und nahm die Schuld für beide auf sich. Druopitee überließ den sechs übrigen verbesserten Scruffies die verbleibenden fünf Spires und nahm Fluffy mit. Du fragst, wie die anderen fünf Scruffies heißen, und er sagt es dir: Huffy, Stuffy, Buffy, Tuffy und Puffy.",
        "Scruffy finally seems more inspired than sad. Looks like he wants to go take down some bad guys.":
            "Scruffy wirkt endlich eher inspiriert als traurig. Sieht aus, als wollte er ein paar Gegner erledigen.",
        "It seems like you've gotta find Scruffy's 5 missing brothers. Scruffy reminds you that they were evil the last time he saw them and to be prepared, but that some may have changed sides since.":
            "Anscheinend musst du Scruffys 5 verschollene Brüder finden. Scruffy erinnert dich daran, dass sie böse waren, als er sie zuletzt gesehen hat, und dass du vorbereitet sein sollst; manche haben inzwischen aber vielleicht die Seiten gewechselt.",
        "You wonder if Trimps came from this Universe, your original one, or somewhere else. Scruffy shrugs.":
            "Du fragst dich, ob die Scruffies aus diesem Universum stammen, aus deinem ursprünglichen oder von woanders. Scruffy zuckt mit den Schultern.",
        "The weather is finally starting to cool back down, you and your Trimps are quite relieved.":
            "Endlich kühlt das Wetter wieder ab, und du und deine Scruffies seid ziemlich erleichtert.",
        "The Trimps are still enjoying the nice weather, and have even found a couple of sweet lakes to swim in!":
            "Die Scruffies genießen immer noch das schöne Wetter und haben sogar ein paar herrliche Seen zum Schwimmen gefunden!",
        // Quagmire's one-word joke (Zone 69 on the Quagmire challenge): the catchphrase stays, the swamp winks back.
        "Giggity":
            "Giggity! Der Sumpf zwinkert dir vielsagend zu.",
        "Your tenacity is inspiring.":
            "Deine Hartnäckigkeit ist inspirierend.",
        "You reach the top of a hill and can see the next 5 Zones stretched out in a valley ahead of you. Towards the end, you see the largest spire you've ever seen. In fact, you can't even see the top of it! It seems to stretch upward infinitely. You look to Scruffy who tells you that one belongs to Huffy. You really hope Huffy isn't evil...":
            "Du erreichst den Gipfel eines Hügels und siehst die nächsten 5 Zonen in einem Tal vor dir ausgebreitet. Gegen Ende siehst du die größte Spire, die du je gesehen hast. Ihre Spitze kannst du nicht einmal erkennen! Sie scheint unendlich weit nach oben zu reichen. Du schaust zu Scruffy, und er sagt dir, dass sie Huffy gehört. Du hoffst sehr, dass Huffy nicht böse ist …",
        "You really don't like Druopitee. You've spent an unknown amount of lifetimes cleaning up his mess, and who knows how many different Universes he's corrupted.":
            "Du kannst Druopitee wirklich nicht leiden. Du hast unzählige Leben damit verbracht, sein Chaos aufzuräumen, und wer weiß, wie viele andere Universen er verdorben hat.",
        "Scruffy tells you that if any of his brothers have come around to the good side since he saw them last, Huffy was the one to do it. Huffy was also the most experienced in hand to hand combat, so you really hope you're not going to have to fight against him.":
            "Scruffy erzählt dir: Wenn einer seiner Brüder seit ihrem letzten Treffen auf die gute Seite gewechselt ist, dann Huffy. Huffy war außerdem der Erfahrenste im Nahkampf, also hoffst du sehr, nicht gegen ihn kämpfen zu müssen.",
        "You're very close to the Spire. You feel like you should be able to smell the Corruption pumping out of it by now but you can't! You take that as a good sign.":
            "Du bist der Spire sehr nahe. Eigentlich müsstest du inzwischen die Corruption riechen, die aus ihr strömt, aber das tust du nicht! Das nimmst du als gutes Zeichen.",
        "As you approach the infinitely tall Spire, a Trimp rushes out and embraces Scruffy. Scruffy introduces you to Huffy, who seems to have also realized that Druopitee is kind of a prick. Huffy lets you know that he managed to destroy the Corruption device at the top, but that it was now crawling with horrible shadowy enemies. Huffy lets you know that he is shielded from the Portal inside the Spire, but that even when you Portal and forget him, he can use your subconscious to help direct him in cleansing the Spire and finding artifacts to make your Trimps stronger.":
            "Als du dich der unendlich hohen Spire näherst, stürmt jemand heraus und umarmt Scruffy. Scruffy stellt dir Huffy vor, der offenbar auch gemerkt hat, dass Druopitee ein ziemlicher Mistkerl ist. Huffy erzählt dir, dass er das Corruption-Gerät an der Spitze zerstören konnte, die Spire aber jetzt von schrecklichen, schattenhaften Gegnern wimmelt. In der Spire ist er vor dem Portal geschützt, sagt Huffy, und selbst wenn du durch das Portal gehst und ihn vergisst, kann er sich von deinem Unterbewusstsein lenken lassen, um die Spire zu säubern und Artefakte zu finden, die deine Scruffies stärker machen.",
        "Huffy is cool and all but you miss Fluffy, you should go visit him soon.":
            "Huffy ist ja ganz cool, aber du vermisst Fluffy. Du solltest ihn bald besuchen.",
        "You thought you saw Druopitee but it was just a tree. On closer inspection it doesn't even look anything like him at all.":
            "Du dachtest, du hättest Druopitee gesehen, aber es war nur ein Baum. Bei näherem Hinsehen sieht er ihm nicht einmal entfernt ähnlich.",
        "This zone feels needy, like it wants your help with something.":
            "Diese Zone wirkt bedürftig, als wollte sie deine Hilfe bei irgendetwas.",
        "As you clear another Zone, Scruffy sits you down for another story. Excited to hear more about Fluffy and Scruffy's history together, you listen intently. Scruffy just rambles about gems and how we could be rich selling jewelry then starts dancing. Seems like Scruffy's been fermenting berries again.":
            "Als du eine weitere Zone geräumt hast, setzt sich Scruffy mit dir für eine weitere Geschichte hin. Du bist gespannt, mehr über die gemeinsame Vergangenheit von Fluffy und Scruffy zu hören, und hörst aufmerksam zu. Scruffy faselt nur von Edelsteinen und davon, wie reich wir mit Schmuck werden könnten, und fängt dann an zu tanzen. Sieht aus, als hätte Scruffy wieder Beeren vergären lassen.",
        "Scruffy created some sort of instrument out of a Snimp and some wood that he calls the Riflunger. It makes better music than you expected, but you wouldn't buy any albums.":
            "Scruffy hat aus einem Slitherkin und etwas Holz eine Art Instrument gebaut, das er Riflunger nennt. Es klingt besser als erwartet, aber Alben würdest du keine kaufen.",
        "Scruffy lets you know that Fluffy was the first modified Trimp created by Druopitee, and was always Druopitee's favorite. Druopitee was probably extra pissed when Fluffy was the one who rebelled and destroyed a couple Spires, that's probably why he was caged when you found him.":
            "Scruffy erzählt dir, dass Fluffy der erste veränderte Scruffy war, den Druopitee erschaffen hat, und immer sein Liebling. Druopitee war bestimmt besonders sauer, als ausgerechnet Fluffy rebellierte und ein paar Spires zerstörte. Wahrscheinlich saß er deshalb in einem Käfig, als du ihn gefunden hast.",
        "There is an extremely chaotic energy flowing around this Zone.":
            "In dieser Zone fließt eine extrem chaotische Energie.",
        "3 or 4 zones ahead of you, you see the biggest storm you've ever seen in your lives. You'd love to find some way to go around it, but it doesn't seem possible.":
            "3 oder 4 Zonen vor dir siehst du den größten Sturm deines Lebens. Du würdest gern einen Weg drumherum finden, aber das scheint unmöglich.",
        "The storm is raging! Your Trimps are flying each other as kites.":
            "Der Sturm tobt! Deine Scruffies lassen einander als Drachen steigen.",
        "You hope Huffy is doing alright back there at the Spire, those Enemies looked pretty scary.":
            "Hoffentlich geht es Huffy dort hinten in der Spire gut. Die Gegner sahen ziemlich furchterregend aus.",
        "You feel a sudden urge to repeat something multiple times expecting different results and wonder what that's all about.":
            "Du verspürst plötzlich den Drang, etwas mehrmals zu wiederholen und dabei andere Ergebnisse zu erwarten, und fragst dich, was das soll.",
        "Scruffy tells you how glad he is that Huffy had come around, but that he's not as hopeful about Stuffy. Stuffy was stubborn and took any opportunity to prove his loyalty to Druopitee. Guess you'll have to find him and see.":
            "Scruffy erzählt dir, wie froh er ist, dass Huffy zur Vernunft gekommen ist, aber bei Stuffy ist er weniger zuversichtlich. Stuffy war stur und nutzte jede Gelegenheit, Druopitee seine Treue zu beweisen. Du wirst ihn wohl finden müssen, dann siehst du ja.",
        "You're having even more trouble than usual trying to control your Trimps here. You and Scruffy debate the pros and cons of asking your Scientists to come up with a mild tranquilizer to put in their food, but you're too busy herding them to come to any conclusion.":
            "Hier fällt es dir noch schwerer als sonst, deine Scruffies im Griff zu behalten. Du und Scruffy wägt das Für und Wider ab, ob deine Forscher ein mildes Beruhigungsmittel fürs Futter entwickeln sollen, aber ihr seid zu sehr damit beschäftigt, sie zusammenzutreiben, um zu einem Ergebnis zu kommen.",
        "Cruffys tells you about the time he put a bucket of water above one of Druopitee's doors as a prank and got banished from the dimension for it.":
            "Cruffys erzählt dir, wie er einmal als Streich einen Eimer Wasser über eine von Druopitees Türen gestellt hat und dafür aus der Dimension verbannt wurde.",
        "Scruffy lets you know that they had another brother named Cruffys who was banished from this dimension before he even had a chance to be assigned a Spire.":
            "Scruffy erzählt dir, dass sie noch einen Bruder namens Cruffys hatten, der aus dieser Dimension verbannt wurde, bevor er überhaupt eine Spire zugeteilt bekommen konnte.",
        "This Zone is filled with bugs and is NOT a great spot to have a picnic.":
            "Diese Zone ist voller Käfer und KEIN guter Ort für ein Picknick.",
        "Scruffy plays his Riflunger while Cruffys sings, and you really wish you had some earplugs or something.":
            "Scruffy spielt auf seinem Riflunger, während Cruffys singt, und du wünschtest wirklich, du hättest Ohrstöpsel oder so.",
        "You wonder if you'll ever get the chance to meet Cruffys. Maybe your Portal can bring you to his dimension some day.":
            "Du fragst dich, ob du Cruffys wohl jemals kennenlernen wirst. Vielleicht bringt dich dein Portal eines Tages in seine Dimension.",
        "Some new Trimp reinforcements have brought a Z1 Turtlimp up with them in a box. The Trimps take turns feeding it and they're doing a good job taking care of it!":
            "Ein paar neue Scruffy-Verstärkungen haben einen Z1-Shellby in einer Kiste mitgebracht. Die Scruffies füttern ihn abwechselnd und kümmern sich richtig gut um ihn!",
        "One of the Trimps on feeding duty was a bit confused and seems to have eaten the Turtlimp.":
            "Einer der Scruffies mit Fütterungsdienst war etwas verwirrt und hat den Shellby anscheinend gegessen.",
        "Huffy pops a quick message into your head to let you know he's doing fine in the Spire!":
            "Huffy schickt dir kurz eine Nachricht in den Kopf, um dir zu sagen, dass es ihm in der Spire gut geht!",
        "Huffy pops a message into your head stating that as much as he likes constantly losing, he would appreciate a little help!":
            "Huffy schickt dir eine Nachricht in den Kopf: So sehr er es mag, ständig zu verlieren, über ein bisschen Hilfe würde er sich freuen!",
        "As you near a gigantic lake, you notice that this part of the World is becoming filled with wild varieties of plants you've never seen before. You've already taught your Trimps not to eat strange plants, but it looks like it's time for a reminder.":
            "Als du dich einem riesigen See näherst, bemerkst du, dass dieser Teil der Welt immer voller wilder Pflanzenarten wird, die du noch nie gesehen hast. Du hast deinen Scruffies zwar schon beigebracht, keine fremden Pflanzen zu essen, aber es sieht nach Zeit für eine Erinnerung aus.",
        "Within the center of the gigantic lake is a large island full of rubble as if a large structure had collapsed here. The stones remind you a lot of Huffy's spire, though there is an infinitely smaller number of the stones than what you'd expect make up the other one. This must have been Fluffy's Spire! You look proudly at the rubble, knowing everything Fluffy sacrificed to rid the world of the evil that was once here.":
            "Mitten im riesigen See liegt eine große Insel voller Trümmer, als wäre hier ein großes Bauwerk eingestürzt. Die Steine erinnern dich stark an Huffys Spire, auch wenn es unendlich viel weniger Steine sind, als du bei der anderen erwarten würdest. Das muss Fluffys Spire gewesen sein! Stolz betrachtest du die Trümmer und denkst an alles, was Fluffy geopfert hat, um die Welt von dem Bösen zu befreien, das einst hier war.",
        "The plant biodiversity around this Zone is incredible, it feels like this Zone is its own isolated ecosystem. The ground around here must be extremely arable.":
            "Die Pflanzenvielfalt rund um diese Zone ist unglaublich. Es fühlt sich an, als wäre diese Zone ein eigenes, abgeschlossenes Ökosystem. Der Boden hier muss extrem fruchtbar sein.",
        "As you're walking through your town, you walk past Scruffy and notice his fur has seemed to change colors slightly. You think to yourself that it's strange, but what's even stranger is that he seems bewildered by the town he helped create, and he does not look happy. Out of the corner of your eye, you also spot Scruffy, but this Scruffy has the expected fur color. You gulp as you realize that this must be one of the other brothers, and you hope he's friendly!":
            "Als du durch deine Stadt gehst, kommst du an Scruffy vorbei und bemerkst, dass sein Fell die Farbe leicht verändert zu haben scheint. Du findest das seltsam, aber noch seltsamer ist, dass er die Stadt, die er mit aufgebaut hat, ganz verwirrt betrachtet und gar nicht glücklich aussieht. Aus dem Augenwinkel entdeckst du auch Scruffy, aber dieser Scruffy hat die erwartete Fellfarbe. Du schluckst, als dir klar wird, dass das einer der anderen Brüder sein muss, und hoffst, dass er freundlich ist!",
        "After avoiding you as best as he could, you and Scruffy finally corner the new -uffy for some questioning. Scruffy immediately recognizes Stuffy, but doesn't seem happy at all to see him. Stuffy informs you that you're polluting the planet with all your smelting and forestry, and that he wants you to shut everything down and return to nature. Scruffy protests, arguing that our cause is worth it and that Druopitee's work must be destroyed at any costs. With that, Stuffy swears to stop you, then he flees into the forest. That probably won't be the last you see of Stuffy.":
            "Nachdem er dir so gut es ging aus dem Weg gegangen ist, stellen du und Scruffy den neuen -uffy endlich zur Rede. Scruffy erkennt Stuffy sofort, freut sich aber überhaupt nicht, ihn zu sehen. Stuffy wirft dir vor, mit deiner ganzen Verhüttung und Forstwirtschaft den Planeten zu verschmutzen, und verlangt, dass du alles abschaltest und zur Natur zurückkehrst. Scruffy widerspricht: Unsere Sache sei es wert, und Druopitees Werk müsse um jeden Preis zerstört werden. Daraufhin schwört Stuffy, dich aufzuhalten, und flieht in den Wald. Das war bestimmt nicht das letzte Mal, dass du Stuffy siehst.",
        "Scruffy informs you that he was doing some observations of the Zones above 200, and that there seems to be something weird going on that wasn't there last time he checked. He fears that Stuffy has gotten up to no good.":
            "Scruffy erzählt dir, dass er die Zonen über 200 beobachtet hat und dort offenbar etwas Seltsames vor sich geht, das bei seinem letzten Besuch noch nicht da war. Er fürchtet, dass Stuffy etwas im Schilde führt.",
        "This Zone appears to be a giant glacier, and the enemies here have evolved small spikes in their feet to avoid slipping around. Fascinating! Your Trimps seem perfectly comfortable on the ice though, and have taken to sliding around like penguimps rather than walking.":
            "Diese Zone scheint ein riesiger Gletscher zu sein, und den Gegnern hier sind kleine Stacheln an den Füßen gewachsen, damit sie nicht ausrutschen. Faszinierend! Deine Scruffies fühlen sich auf dem Eis aber pudelwohl und rutschen lieber wie Waddlebies herum, statt zu laufen.",
        "Just as you're getting back to your town for some R&R, Scruffy returns from his Stuffy studying voyage. He looks grim. He informs you that he's taken some samples and will do his best to fill you in when you get there, but that every Zone above Z200 seems to contain horribly mutated enemies. He says there's multiple different strains of Mutation up there, and that they can even potentially combine to make super Mutations. You don't really think you like the sound of super Mutations.":
            "Gerade als du für etwas Erholung in deine Stadt zurückkehrst, kommt Scruffy von seiner Stuffy-Forschungsreise zurück. Er sieht finster aus. Er hat Proben genommen und will dich so gut wie möglich aufklären, wenn du dort ankommst, aber jede Zone über Z200 scheint grauenhaft mutierte Gegner zu enthalten. Er sagt, dort oben gebe es mehrere verschiedene Mutationsstämme, die sich sogar zu Supermutationen verbinden können. Supermutationen klingen für dich nicht besonders verlockend.",
        "Scruffy returns from yet another Mutation-studying-session still looking unhappy. He apologizes to you for his brother and swears to help you stop him. He's not sure exactly where Stuffy's Spire is, but he says you'll have to fight through many Zones of Mutated enemies to get there.":
            "Scruffy kommt von einer weiteren Mutations-Untersuchung zurück und sieht immer noch unglücklich aus. Er entschuldigt sich bei dir für seinen Bruder und schwört, dir zu helfen, ihn aufzuhalten. Wo genau Stuffy's Spire steht, weiß er nicht, aber er sagt, du müsstest dich durch viele Zonen voller mutierter Gegner kämpfen, um dorthin zu kommen.",
        "You sit down outside of your town and think about what Stuffy had said. Are you really destroying the planet? As you're thinking about it, a Trimp covered in beeimp stings walks up to you and with a dumb smile, hands you a mostly squished flower. You realize then that of course the Trimps are worth it, and that you'll do anything it takes to stop Stuffy.":
            "Du setzt dich vor deine Stadt und denkst über Stuffys Worte nach. Zerstörst du wirklich den Planeten? Während du darüber nachdenkst, kommt ein von Beeimp-Stichen übersäter Scruffy auf dich zu und reicht dir mit einem dümmlichen Lächeln eine ziemlich zerdrückte Blume. Da wird dir klar, dass die Scruffies es natürlich wert sind und dass du alles tun wirst, um Stuffy aufzuhalten.",
        "Scruffy reminds you that you're getting close to Stuffy's domain, and to watch out for new Mutations on enemies. You ask how you'll know that an enemy is Mutated, and he tells you you'll know.":
            "Scruffy erinnert dich daran, dass du dich Stuffys Reich näherst und auf neue Mutationen bei Gegnern achten sollst. Du fragst, woran du erkennst, dass ein Gegner mutiert ist, und er sagt, das wirst du schon merken.",
        "This Zone is very dark and the grass here is very soft. It's the perfect place for a nap to build up some strength for the Mutated zones!":
            "Diese Zone ist sehr dunkel und das Gras hier sehr weich. Der perfekte Ort für ein Nickerchen, um Kraft für die mutierten Zonen zu sammeln!",
        "From the highest point at this Zone you can clearly see into the next Zone, and you don't like what you see. A handful of enemies seem to be covered in a purple goop, but it's a different purple goop than the one deep in your memories. Something weird is going on in there...":
            "Vom höchsten Punkt dieser Zone siehst du deutlich in die nächste Zone, und was du siehst, gefällt dir nicht. Eine Handvoll Gegner scheint mit lila Glibber überzogen zu sein, aber mit einem anderen lila Glibber als dem tief in deinen Erinnerungen. Da drin geht etwas Seltsames vor …",
        "Scruffy notes your bewilderment at the purple gooped enemies in this Zone, and gives you a quick rundown based on the samples he collected. These are Raging enemies! They're all affected by the 'Rage' mutation, and start with extra strong attacks, but they'll get weaker as you damage them. Scruffy lets you know that these enemies will drop Mutated Seeds, which you could potentially use to improve your Trimps! They'll also drop a bit of extra Radon for our Portal Device. Go kill them!":
            "Scruffy bemerkt deine Verwirrung über die lila verglibberten Gegner in dieser Zone und gibt dir anhand seiner Proben einen kurzen Überblick. Das sind wütende Gegner! Sie stehen alle unter der Mutation ‚Rage‘, beginnen mit besonders starken Angriffen, werden aber schwächer, je mehr Schaden du ihnen zufügst. Scruffy erklärt dir, dass diese Gegner Mutated Seeds fallen lassen, mit denen du deine Scruffies womöglich verbessern kannst! Außerdem lassen sie etwas zusätzliches Radon für das Portal-Gerät fallen. Los, erledige sie!",
        "What's this?! Another type of Mutated enemy? Scruffy tells you that the strange looking enemies on this Zone are affected by what he calls 'Cell Compression', and that the first green enemy has consumed all of the green cells after it. The first green cell will be extra tough as it has all the stats of the other green cells after it, but if you manage to kill it you can just walk right through the cells behind it and pick up your loot. Scruffy lets you know you'll find even more Mutated Seeds here!":
            "Was ist das denn?! Noch eine Art mutierter Gegner? Scruffy erklärt dir, dass die seltsam aussehenden Gegner in dieser Zone unter dem stehen, was er ‚Cell Compression‘ nennt: Der erste grüne Gegner hat alle grünen Felder nach ihm verschlungen. Das erste grüne Feld ist besonders zäh, weil es die Werte aller grünen Felder danach hat, aber wenn du es erledigst, kannst du einfach durch die Felder dahinter spazieren und deine Beute einsammeln. Scruffy sagt, hier findest du sogar noch mehr Mutated Seeds!",
        "Good gravelimp, there's another type of Mutated enemy here! You turn to Scruffy who was already preparing his notes. He tells you that this is what he calls the 'Nova' mutation. The enemy in the center of that mutation appears to be radioactive, and it's mutating the cells around itself. The center cell is extremely weak but will release a Nova whenever it's damaged, debuffing your Trimps to make them deal less damage and take more damage until the end of the Zone. The other nearby mutated cells have extremely high attack but reduced health. And of course, you'll find another large batch of Mutated Seeds!":
            "Heiliger Pebblekin, hier gibt es noch eine Art mutierter Gegner! Du drehst dich zu Scruffy um, der seine Notizen schon bereithält. Er erklärt dir, dass dies die Mutation ist, die er ‚Nova‘ nennt. Der Gegner in der Mitte dieser Mutation scheint radioaktiv zu sein und mutiert die Felder um sich herum. Das mittlere Feld ist extrem schwach, löst aber bei jedem Schaden eine Nova aus, die deine Scruffies bis zum Ende der Zone schwächt: Sie verursachen weniger Schaden und nehmen mehr Schaden. Die anderen mutierten Felder in der Nähe haben extrem hohe Attack, aber weniger Health. Und natürlich findest du wieder eine große Ladung Mutated Seeds!",
        "As you finally pass the Nova Zone and reach the next, you notice yet another new type of Mutation. Scruffy calls this one the 'Row Randomizer', because he says there are stronger enemies in the front of the Zone and weaker enemies in the back. The first Randomized Row you come across will be harder than normal, but the second one will be easier. And of course, Radon and Mutated Seeds!":
            "Als du die Nova-Zone endlich hinter dir lässt und die nächste erreichst, bemerkst du schon wieder eine neue Art von Mutation. Scruffy nennt sie ‚Row Randomizer‘, weil es vorne in der Zone stärkere und hinten schwächere Gegner gibt. Die erste zufällige Reihe, auf die du triffst, ist schwerer als normal, die zweite dafür leichter. Und natürlich: Radon und Mutated Seeds!",
        "Scruffy lets you know that there seems to be no pattern to the repeating of these new Mutations. He warns that they'll appear in larger numbers the closer we get to Stuffy's Spire, and he reminds you that it's possible for one enemy to have more than one of these Mutations available at a time. He urges you to collect as many Mutated Seeds as possible, and to use them at your new Mutator to improve your Trimps. It's the only way to catch up to Stuffy!":
            "Scruffy erklärt dir, dass sich diese neuen Mutationen offenbar ohne Muster wiederholen. Er warnt, dass sie in größerer Zahl auftreten, je näher wir Stuffy's Spire kommen, und erinnert dich daran, dass ein Gegner auch mehrere dieser Mutationen gleichzeitig haben kann. Er drängt dich, so viele Mutated Seeds wie möglich zu sammeln und sie an deinem neuen Mutator einzusetzen, um deine Scruffies zu verbessern. Nur so holst du Stuffy ein!",
        "The mutations seem to show no sign of letting up, but the Trimps like the new colors.":
            "Die Mutationen lassen kein bisschen nach, aber den Scruffies gefallen die neuen Farben.",
        "You spot Scruffy sulking around and go see what's up. He lets you know that you're close to his old Spire and that the scenery is dredging up some bad memories. You want to talk more about his days running a Spire, but the Trimps seem to have started a fire that you should really go attend to.":
            "Du siehst Scruffy herumschmollen und schaust nach, was los ist. Er erzählt dir, dass du nahe an seiner alten Spire bist und die Gegend schlechte Erinnerungen weckt. Du würdest gern mehr über seine Zeit als Herr einer Spire hören, aber die Scruffies scheinen ein Feuer gelegt zu haben, um das du dich wirklich kümmern solltest.",
        "As you exit the horribly charred previous zone, you make a mental note to admonish the miners for teaching your soldiers they could make sparks with their swords.":
            "Als du die schrecklich verkohlte letzte Zone verlässt, nimmst du dir vor, die Bergleute zu rügen, weil sie deinen Soldaten beigebracht haben, mit ihren Schwertern Funken zu schlagen.",
        "The mutation seems to show no signs of letting up, and neither do the urges of your Trimps to roll around in the goop.":
            "Die Mutation lässt kein bisschen nach, und der Drang deiner Scruffies, sich im Glibber zu wälzen, auch nicht.",
        "You've finally stumbled upon the massive pile of rubble that must have been Scruffy's Spire. You can tell he's ashamed for letting Fluffy take the fall for making the tower fall, but you reassure him that nothing good would have come from him being caged as well. You tell him you're glad he's here to help you, and give him a couple pats.":
            "Endlich bist du auf den riesigen Trümmerhaufen gestoßen, der einmal Scruffys Spire gewesen sein muss. Du merkst, dass er sich schämt, weil Fluffy die Schuld für den Einsturz des Turms auf sich genommen hat, aber du versicherst ihm, dass nichts Gutes dabei herausgekommen wäre, wenn man ihn auch eingesperrt hätte. Du sagst ihm, wie froh du bist, dass er hier ist und dir hilft, und tätschelst ihn ein paarmal.",
        "Scruffy seems to be mostly back to his old self, and has even started playing the Riflunger again. You have to admit he's improving, the sound now barely even makes you want to fill your ears with sand!":
            "Scruffy scheint wieder ganz der Alte zu sein und hat sogar wieder angefangen, Riflunger zu spielen. Zugegeben, er wird besser: Bei dem Klang willst du dir kaum noch Sand in die Ohren stopfen!",
        "Three Trimps tried taming two tempermental Titimps. They thought Titimps treasured trash, thus they took turns throwing things toward the Titimps. Thoroughly terrified, the tormented Titimps trapped the Trimps, took their tools, then took to the trail.":
            "Drei Scruffies wollten zwei launische Brawnkins bändigen. Sie dachten, Brawnkins bewahrten bergeweise Abfall, also bewarfen sie die Brawnkins abwechselnd mit allerlei Zeug. Bis ins Mark verängstigt, banden die bedrängten Brawnkins die Scruffies fest, bemächtigten sich ihres Werkzeugs und brachen dann auf.",
        "You spot Stuffy sneaking around the camp, and decide to engage sneak mode yourself to see what he's up to. However you're not very good at sneak mode, and he quickly notices you and scurries off.":
            "Du siehst Stuffy durchs Lager schleichen und schaltest selbst in den Schleichmodus, um herauszufinden, was er vorhat. Leider bist du nicht besonders gut im Schleichmodus; er bemerkt dich schnell und huscht davon.",
        "Oh goodness, there are two different Mutations on this Zone! Scruffy warns you that multiple mutations can affect the same enemy, leading to some crazy combinations. You're split on how you feel about this. On one hand, the mutated enemies are monstrous and the goop is clearly not natural, but on the other hand the colors look pretty cool. You'll have to reflect on this for a bit.":
            "Du meine Güte, in dieser Zone gibt es zwei verschiedene Mutationen! Scruffy warnt dich, dass mehrere Mutationen denselben Gegner treffen können, was zu verrückten Kombinationen führt. Du bist hin- und hergerissen. Einerseits sind die mutierten Gegner monströs und der Glibber eindeutig nicht natürlich, andererseits sehen die Farben ziemlich cool aus. Darüber musst du eine Weile nachdenken.",
        "You're relaxing at the end of a Zone, minding your own business, when suddenly you hear a loud explosion in the direction of the camp. You run over to assess the damage and assist Scruffy in calming the frantic Trimps. As you look around, you see a message written on a nearby rock that says \"Stuffy was here\".":
            "Du entspannst dich gerade am Ende einer Zone und kümmerst dich um deinen eigenen Kram, als du plötzlich eine laute Explosion aus Richtung des Lagers hörst. Du rennst hin, um den Schaden zu begutachten, und hilfst Scruffy, die panischen Scruffies zu beruhigen. Als du dich umsiehst, entdeckst du auf einem Stein in der Nähe die Botschaft ‚Stuffy war hier‘.",
        "Scruffy informs you that he's finally been able to detect Stuffy's Spire, due to the presence of a new Mutation there that exists nowhere else. He says you're only 35 Zones away now, and to be ready.":
            "Scruffy berichtet dir, dass er Stuffy's Spire endlich orten konnte, weil es dort eine neue Mutation gibt, die sonst nirgendwo vorkommt. Er sagt, du bist jetzt nur noch 35 Zonen entfernt und sollst bereit sein.",
        "Scruffy has been busy studying Stuffy's Spire, and comes to you with more news. It sounds like Stuffy's Spire is certainly not the only one on the planet pumping out Mutation, but that taking it down is the first step on the path to saving this Universe.":
            "Scruffy war fleißig damit beschäftigt, Stuffy's Spire zu untersuchen, und kommt mit Neuigkeiten zu dir. Stuffy's Spire ist offenbar keineswegs die einzige auf dem Planeten, die Mutation ausstößt, aber sie zu Fall zu bringen, ist der erste Schritt zur Rettung dieses Universums.",
        "The planet continues to look even more and more mutated as you press further into the Zones with the intact Spires. You shudder at the thought of what the Zones might look like deeper in.":
            "Der Planet sieht immer mutierter aus, je weiter du in die Zonen mit den intakten Spires vordringst. Dich schaudert bei dem Gedanken, wie die Zonen weiter drinnen aussehen könnten.",
        "You can't really overstate the amount of goo all over the place at these Zones, certainly an effect of the Mutations. The Trimps seem to enjoy throwing it at eachother in some new game they've invented.":
            "Man kann gar nicht übertreiben, wie viel Glibber in diesen Zonen überall herumliegt, sicher eine Folge der Mutationen. Die Scruffies bewerfen sich damit begeistert in einem neuen Spiel, das sie erfunden haben.",
        "You still can't quite see the Spire yet, but you can feel it in your bones.":
            "Die Spire kannst du noch nicht ganz sehen, aber du spürst sie in den Knochen.",
        "As you cross into the next Zone, you finally get a glimpse of the Spire in the distance. It looks considerably less destroyed than the two previous Spires. You've got your work cut out for you.":
            "Als du die nächste Zone betrittst, erhaschst du endlich einen Blick auf die Spire in der Ferne. Sie sieht deutlich weniger zerstört aus als die beiden vorherigen Spires. Da hast du dir einiges vorgenommen.",
        "Scruffy knows you did your best back there in the Spire!":
            "Scruffy weiß, dass du dort hinten in der Spire dein Bestes gegeben hast!",
        "Scruffy is impressed with how much of the Spire you've destroyed, before you know it the Spire will be half gone!":
            "Scruffy ist beeindruckt, wie viel von der Spire du schon zerstört hast. Ehe du dich versiehst, ist die Spire zur Hälfte weg!",
        "Behind you, you can see the remnants of the Spire. It might not be completely gone yet but it's definitely looking a bit small!":
            "Hinter dir siehst du die Überreste der Spire. Ganz verschwunden ist sie noch nicht, aber sie sieht definitiv schon ziemlich klein aus!",
        "The Spire has been so destroyed that you can't even see it behind you from one Zone away. Any lifetime now, Stuffy will pay!":
            "Die Spire ist so zerstört, dass du sie schon eine Zone weiter hinter dir nicht mehr sehen kannst. Ein, zwei Leben noch, dann wird Stuffy dafür bezahlen!",
        "You look behind you and let out a big sigh of relief. It sure feels good knowing you stopped Stuffy! Now who's next...":
            "Du blickst hinter dich und seufzt erleichtert auf. Es tut richtig gut zu wissen, dass du Stuffy aufgehalten hast! Und wer ist als Nächstes dran …",
        "You're pushing deeper between two active Spires. The air feels thicker and thicker every Zone, but you continue on and know you'll stop Stuffy soon.":
            "Du dringst tiefer zwischen zwei aktive Spires vor. Die Luft wird mit jeder Zone dicker, aber du machst weiter und weißt, dass du Stuffy bald aufhalten wirst.",
        "You hear a familiar sound behind you and turn around to see none other than Stuffy! He makes a few taunting gestures at you and then runs away. You ask a Trimp to throw something at him but the Trimp misses.":
            "Hinter dir hörst du ein vertrautes Geräusch, drehst dich um und siehst niemand anderen als Stuffy! Er macht ein paar spöttische Gesten in deine Richtung und rennt dann weg. Du bittest einen Scruffy, etwas nach ihm zu werfen, aber der Scruffy verfehlt ihn.",
        "You hear a familiar sound behind you and turn around to see none other than Stuffy! He makes a few taunting gestures at you and then runs away. You ask a Trimp to throw something at him and the Trimp nails him right in the back of the head with a Snimp carcass. Hah!":
            "Hinter dir hörst du ein vertrautes Geräusch, drehst dich um und siehst niemand anderen als Stuffy! Er macht ein paar spöttische Gesten in deine Richtung und rennt dann weg. Du bittest einen Scruffy, etwas nach ihm zu werfen, und der Scruffy trifft ihn mit einem Slitherkin-Kadaver direkt am Hinterkopf. Ha!",
        "Scruffy walks up to you and tells you that you're awesome. You already knew that but it's still nice to hear from time to time.":
            "Scruffy kommt zu dir und sagt dir, dass du großartig bist. Das wusstest du schon, aber es ist trotzdem schön, es ab und zu zu hören.",
        "You return to camp to find a hole that wasn't there before and two Trimps inside. Clearly the work of Stuffy, you really gotta do something about that guy! You get to work building a ladder, but the Trimps climb out of the hole on their own before you finish it.":
            "Zurück im Lager findest du ein Loch, das vorher nicht da war, und zwei Scruffies darin. Eindeutig Stuffys Werk, gegen den Kerl musst du wirklich etwas unternehmen! Du fängst an, eine Leiter zu bauen, aber die Scruffies klettern von selbst aus dem Loch, bevor du fertig bist.",
        "You return to camp to find a hole that wasn't there before and two Trimps inside. You ask Scruffy what happened to them and he tells you they tried to dig a pool then fell asleep. Those crazy Trimps!":
            "Zurück im Lager findest du ein Loch, das vorher nicht da war, und zwei Scruffies darin. Du fragst Scruffy, was mit ihnen passiert ist, und er erzählt dir, dass sie einen Pool graben wollten und dabei eingeschlafen sind. Diese verrückten Scruffies!",
        "It's not a windy day but the trees are definitely moving around. Spooky!":
            "Es ist kein windiger Tag, aber die Bäume bewegen sich eindeutig. Gruselig!",
        "It's a beautiful day for a swim with your Trimps! You can't actually fit in the swimming pool your Trimps made, but it'd be a nice day for it if you could.":
            "Ein herrlicher Tag zum Schwimmen mit deinen Scruffies! In den Pool, den deine Scruffies gebaut haben, passt du zwar nicht hinein, aber wenn doch, wäre es ein schöner Tag dafür.",
        "The air is getting incredibly thick this far out between two active Spires. Your Trimps look like they're starting to slow down a bit, so you give them an encouraging speech. It didn't seem to help much but they can't say you didn't try.":
            "So weit draußen zwischen zwei aktiven Spires wird die Luft unglaublich dick. Deine Scruffies scheinen etwas langsamer zu werden, also hältst du ihnen eine aufmunternde Rede. Viel geholfen hat sie anscheinend nicht, aber sie können nicht behaupten, du hättest es nicht versucht.",
        "The air is thick out this far between two active Spires, but so are your Trimps from all the Spire cells you've cleared. They barely even seem to notice!":
            "So weit draußen zwischen zwei aktiven Spires ist die Luft dick, aber das sind deine Scruffies dank all der geräumten Spire-Felder auch. Sie scheinen es kaum zu bemerken!",
        "Dang your Trimps are looking beefy. Clearing Stuffy's Spire has certainly put them in tip-top shape! You point this out to Scruffy who says they'll need it if you ever find Buffy.":
            "Mann, sehen deine Scruffies muskulös aus. Das Räumen von Stuffy's Spire hat sie wirklich in Topform gebracht! Du weist Scruffy darauf hin, und er meint, das werden sie auch brauchen, falls du jemals Buffy findest."
    };
    // Zone texts with a number inside (getters that use mutations, soldiers or the population).
    const zonePatterns = [
        [whole(["The corruption seems to be more pronounced the closer you get to the Spire. Looks like there's ", N, ' of em now.']),
            (_, n) => 'Je näher du der Spire kommst, desto stärker scheint die Corruption zu werden. Sieht aus, als wären es jetzt schon ' + n + ' davon.'],
        [whole(['During a boring night while waiting to cross a particularly rough Magma river, you managed to teach your Trimps how to stack on each other to create some funny shapes. You almost feel bad for the first Snimp to come across ', N, ' Trimps stuck together in the shape of a humongous Mongooseimp.']),
            (_, n) => 'In einer langweiligen Nacht, während ihr darauf wartet, einen besonders wilden Magmafluss zu überqueren, bringst du deinen Scruffies bei, aufeinanderzuklettern und lustige Figuren zu bilden. Fast tut dir der erste Slitherkin leid, der auf ' + n + ' Scruffies stößt, die zusammen die Form eines riesigen Mongooseimp bilden.'],
        [whole(['The next Zone is connected to this one by a large downward sloping hill. All ', N, ' of your Trimps all tuck themselves into a ball and roll down it, what a sight!']),
            (_, n) => 'Die nächste Zone ist mit dieser durch einen großen, abfallenden Hang verbunden. Alle ' + n + ' deiner Scruffies rollen sich zu einer Kugel zusammen und kullern hinunter. Was für ein Anblick!'],
        [whole(['Scruffy organized a surprise party for you while you were in the last Zone. He even managed to somehow get all ', N, ' of your Trimps to hide behind couches and things so you would actually be surprised, what a guy!']),
            (_, n) => 'Scruffy hat eine Überraschungsparty für dich organisiert, während du in der letzten Zone warst. Er hat es sogar irgendwie geschafft, alle ' + n + ' deiner Scruffies hinter Sofas und so zu verstecken, damit du wirklich überrascht bist. Was für ein Kerl!']
    ];
    const zoneProbe = /^(?:The corruption seems|During a boring night|The next Zone is connected|Scruffy organized a surprise)/;
    // Spire story: the original joins a story part (getSpireStory) and a reward sentence into one line, so each English
    // part is a piece here; a line becomes German only when all of its pieces are known (no mixed lines).
    const spire = {
        "Everything in this Spire seems less tidy than the last, he never thought the first was something you could pass. You find a small note amongst some Nullifium.<br/><span class='spirePoem'>Healthy mutation bad...<br/>Slows delirium</span>Well that doesn't really sound like a bad thing.":
            "Diese Spire wirkt schlampiger als die vorher, das ist klar; dass du die erste schaffen könntest, hielt er für unvorstellbar. Zwischen etwas Nullifium findest du einen kleinen Zettel.<br/><span class='spirePoem'>Healthy-Mutation schlecht …<br/>Bremst Delirium</span>Na ja, das klingt eigentlich nicht nach etwas Schlechtem.",
        "As you near the halfway point without too much strife, the Spire itself seems to become alive. You don't know what could be activating it since Druopitee is dead, so you keep your head down and you watch where you tread.<br/><br/>There's also some little containers floating a tiny bit off the ground, so you go check em out.":
            "Ohne viel Mühe kommst du der Hälfte nah im Nu, da erwacht die Spire selbst zum Leben und gibt keine Ruh. Was sie antreibt, weißt du nicht, Druopitee ist ja tot, also ziehst du den Kopf ein und achtest auf jeden Tritt, wie es die Vorsicht gebot.<br/><br/>Außerdem schweben ein paar kleine Behälter knapp über dem Boden, also siehst du sie dir mal an.",
        "A humming vibration suddenly fills the air, and a voice booms from the walls. <span class='spirePoem'>There is a piece of me in every last Spire<br/>I will ensure that Corruption is never retired<br/>Though your resolve is something that I admire<br/>Your little plan will surely backfire<br/></span>So it seems like all of the Spires are actually sentient thanks to Druopitee. You're just glad the narrator isn't trying to do the poetry anymore. Hey wait...<br/><br/>":
            "Plötzlich erfüllt ein summendes Vibrieren die Luft, und eine Stimme dröhnt aus den Wänden. <span class='spirePoem'>Ein Stück von mir steckt in jeder einzelnen Spire<br/>Die Corruption geht nie in Rente, das schwöre ich dir<br/>Auch wenn ich deine Entschlossenheit bewundere schier<br/>Dein kleiner Plan geht nach hinten los, glaub es mir<br/></span>Dank Druopitee scheinen also alle Spires ein Bewusstsein zu haben. Du bist nur froh, dass der Erzähler nicht mehr versucht zu dichten. Moment mal …<br/><br/>",
        "<span class='spirePoem'>I see you found my notes on my Healthy mutation<br/>I bet you even think it could be your salvation<br/>Improving this world must be quite the temptation<br/>But your journey will surely end in frustration</span>Well, you definitely want to get your hands on some of that Healthy mutation now.":
            "<span class='spirePoem'>Du hast meine Notizen gefunden zur Healthy-Mutation<br/>Und hältst sie bestimmt schon für deine Erlösung, deine Mission<br/>Die Welt zu verbessern, ist eine große Versuchung, ich weiß es schon<br/>Doch deine Reise endet gewiss in Frustration</span>Jetzt willst du auf jeden Fall etwas von dieser Healthy-Mutation in die Finger bekommen.",
        "Nothing here but a bunch of boxes, so you decide to rummage through them.":
            "Hier gibt es nichts außer einem Haufen Kisten, also wühlst du darin herum.",
        "<span class='spirePoem'>Even if you were able, which you surely are not<br/>A Healthier world would not hasten your trot<br/>For there's strength in Health and you would be distraught<br/>At the difficult challenge you yourself had wrought</span>It sounds like he's trying to tell you that the Healthy mutation would make your enemies even stronger. Still seems like releasing it would be the right thing to do, though.":
            "<span class='spirePoem'>Selbst wenn du es könntest, was du gewiss nicht kannst<br/>Eine gesündere Welt beschleunigt nicht deinen Gang<br/>Denn in Health liegt Stärke, und du wärst voller Angst<br/>Vor der schweren Prüfung, die du selbst dir errangst</span>Es klingt, als wolle er dir sagen, dass die Healthy-Mutation deine Gegner noch stärker machen würde. Sie freizusetzen, scheint trotzdem das Richtige zu sein.",
        "As the Echo of Druopitee falls, you notice a large tank of some brown looking liquid, and you see pipes and tubes running from it to the top of the Spire. A label on the tank seems to indicate that this is the Healthy mutation and that you shouldn't touch it. But you know that what you want and what Druopitee wants are different things, so you start turning all the nozzles you can find. A fine brown mist begins to spout from the top of the Spire and you can tell that the world is finally healing. Now you just hope he was lying about this making the enemies stronger...":
            "Als das Echo of Druopitee fällt, bemerkst du einen großen Tank mit einer bräunlichen Flüssigkeit, und Rohre und Schläuche führen von ihm zur Spitze der Spire. Laut einem Etikett auf dem Tank ist das die Healthy-Mutation, und anfassen sollst du sie nicht. Aber du weißt, dass du und Druopitee nicht dasselbe wollt, also drehst du an allen Ventilen, die du finden kannst. Aus der Spitze der Spire sprüht ein feiner brauner Nebel, und du spürst, dass die Welt endlich heilt. Jetzt hoffst du nur, dass er gelogen hat, als er sagte, das würde die Gegner stärker machen …",
        "There seems to be a pattern here of each spire looking considerably more trashed than the one before it. The walls feel cold and the vibration inside is very faint. Nobody's watching you, so you dig around looking for some stuff to take.":
            "Hier zeichnet sich ein Muster ab: Jede Spire sieht deutlich heruntergekommener aus als die vorige. Die Wände fühlen sich kalt an, und das Vibrieren im Inneren ist ganz schwach. Niemand sieht hin, also stöberst du nach Sachen, die du mitnehmen kannst.",
        "The vibrations within the walls grow stronger with each step you take towards the top. The air has become noticeably warmer, and you expect the walls to start talking to you again soon.":
            "Mit jedem Schritt nach oben wird das Vibrieren in den Wänden stärker. Die Luft ist spürbar wärmer geworden, und du rechnest damit, dass die Wände bald wieder mit dir reden.",
        "<span class='spirePoem'>WHAT<br/>WHO<br/>How...</span>That didn't seem very coherent. It seems like destroying his Echo in the last Spire has made some sort of impact.":
            "<span class='spirePoem'>WAS<br/>WER<br/>Wie …</span>Das klang nicht sehr zusammenhängend. Die Zerstörung seines Echos in der letzten Spire scheint Wirkung gezeigt zu haben.",
        "<span class='spirePoem'>I see that you're attempting some planetary healing<br/>Leaving me steaming in an unappealing feeling<br/>Your freewheeling and stealing has just reached the ceiling<br/>Now commence kneeling or be sent off reeling</span>At least he's gained enough consciousness back to continue with the threats. You know that now is not the time to back down.":
            "<span class='spirePoem'>Ich sehe, du willst den Planeten kurieren<br/>Und lässt mich vor Wut hier kochen und frieren<br/>Dein dreistes Rauben und Plündern wird nicht länger florieren<br/>Jetzt knie nieder, sonst wirst du alles verlieren</span>Immerhin hat er genug Bewusstsein zurück, um weiter zu drohen. Du weißt, dass jetzt nicht der Moment ist, klein beizugeben.",
        "<span class='spirePoem'>It's obvious that you want the Corruption to slow<br/>So I'll point out something you might not yet know<br/>My Spires are infinite, there is no plateau<br/>You are doomed and you've been so since long long ago</span>His Spires might be infinite, but it's not possible for his consciousness to be. You decide you'll worry about the rest of the spires once you've beaten Druopitee into nothingness.":
            "<span class='spirePoem'>Du willst die Corruption bremsen, das ist klar<br/>Drum sag ich dir etwas, was dir neu ist sogar<br/>Meine Spires gibt es unendlich oft, ganz und gar<br/>Du bist verloren, und das schon seit so manchem Jahr</span>Seine Spires mögen unendlich sein, sein Bewusstsein kann es nicht. Um die übrigen Spires kümmerst du dich, sobald du Druopitee ins Nichts geprügelt hast.",
        "<span class='spirePoem'>Still you climb on, won't your strength ever waver?<br/>You're determined to be this planet's true savior?<br/>Stop to reconsider, we could be something greater<br/>Or continue your path as a time traveling slaver</span>Slaver?! Your Trimps all know that they're free to leave whenever they want. He's just trying to get under your skin!":
            "<span class='spirePoem'>Du kletterst weiter, schwindet deine Kraft denn nimmermehr?<br/>Willst du wirklich dieses Planeten Retter sein, so sehr?<br/>Denk noch mal nach, gemeinsam wären wir viel mehr<br/>Oder geh deinen Weg als zeitreisender Sklaventreiber, bitte sehr</span>Sklaventreiber?! Deine Scruffies wissen alle, dass sie jederzeit gehen dürfen. Er will dich nur provozieren!",
        "Well, that's one Druopitee and two Echoes of Druopitee down now. He says that he has infinite Spires and infinite versions of himself, but you could tell at the end there that his Echoes are losing power. You might be able to knock the sentience out of all of his Spires by just clearing one more! You set your sights 100 Zones forward, turn some more nozzles to spread some more Health around the world, you take your helium, spit on the floor of the Spire, and move on.":
            "Tja, das wären dann ein Druopitee und zwei Echos von Druopitee. Er behauptet, unendlich viele Spires und unendlich viele Versionen von sich zu haben, aber am Ende hast du gemerkt, dass seine Echos an Kraft verlieren. Vielleicht kannst du allen seinen Spires mit nur einer weiteren das Bewusstsein austreiben! Du nimmst das Ziel 100 Zonen weiter ins Visier, drehst an ein paar weiteren Ventilen, um mehr Gesundheit in der Welt zu verteilen, nimmst dein Helium, spuckst auf den Boden der Spire und ziehst weiter.",
        "As you guessed before you even stepped in, this Spire is in even worse condition than the one before. The air is colder, the walls are more still, and there's a feeling of vacancy. Might as well look for stuff to take!":
            "Wie du schon vor dem Betreten vermutet hast, ist diese Spire in noch schlechterem Zustand als die vorige. Die Luft ist kälter, die Wände sind stiller, und alles fühlt sich verlassen an. Dann kannst du ja gleich nach Sachen zum Mitnehmen suchen!",
        "You wonder if the Echo of Druopitee will even be able to speak anymore. You know he'll be at the top waiting, just like the infinite other Spires, but maybe he'll just leave you be this time.":
            "Du fragst dich, ob das Echo of Druopitee überhaupt noch sprechen kann. Du weißt, dass er oben wartet, wie in den unendlich vielen anderen Spires, aber vielleicht lässt er dich diesmal einfach in Ruhe.",
        "The Spire is warming up again. Maybe Druopitee will make his final appearance soon.":
            "Die Spire wird wieder wärmer. Vielleicht hat Druopitee bald seinen letzten Auftritt.",
        "<span class='spirePoem'>Please just go around, there's nothing to see<br/>Why is my demise something you must guarantee?<br/>I beg you once more, please hear my plea<br/>We could rule for all time, just you and me</span>No thanks, Druopitee. It's kinda nice to see him scared though!":
            "<span class='spirePoem'>Geh doch einfach vorbei, hier gibt's nichts zu sehen<br/>Warum muss mein Untergang unbedingt geschehen?<br/>Ich bitte dich noch einmal, hör auf mein Flehen<br/>Gemeinsam könnten wir ewig über allem stehen</span>Nein danke, Druopitee. Irgendwie schön, ihn mal ängstlich zu sehen!",
        "<span class='spirePoem'>Well here is something I wouldn't normally say<br/>Since it seems like you won't be going away<br/>Each of my Echoes you slay makes my mind decay<br/>I may not be able to communicate after today</span>Yes, that was becoming pretty obvious. His mind must really be decaying fast if he thought this admission would be anything other than motivating.":
            "<span class='spirePoem'>Nun sag ich etwas, das ich sonst nie sagen mag<br/>Da du ja offenbar nicht gehst, Tag für Tag<br/>Jedes Echo, das du erschlägst, ist für meinen Geist ein Schlag<br/>Vielleicht bin ich ab morgen stumm, wer weiß, was ich vermag</span>Ja, das war schon ziemlich offensichtlich. Sein Geist muss wirklich schnell verfallen, wenn er dachte, dieses Geständnis würde dich nicht noch mehr anspornen.",
        "<span class='spirePoem'>Why don't you care that you're making things harder?<br/>To repair the planet you'd give enemies armor?<br/>When I brought you here, I thought you'd be smarter<br/>But it seems like there's no room left to barter</span>No, there's not. You're almost there.":
            "<span class='spirePoem'>Warum ist's dir egal, dass du alles erschwerst?<br/>Für den Planeten gibst du den Feinden Rüstung, wenn du's begehrst?<br/>Als ich dich herbrachte, dachte ich, dass du klüger wärst<br/>Doch zu verhandeln gibt es wohl nichts mehr, wie du mich lehrst</span>Nein, gibt es nicht. Du bist fast da.",
        "As this third Echo of Druopitee falls, the Spire suddenly feels twice as cold. Druopitee told you that he placed infinite versions of himself in infinite Spires, but his will should no longer be conscious in any of them. You turn another set of knobs to release some more of the Healthy mutation into the world, and you figure there's nothing better to do than to keep looking for more to release. You just wouldn't be surprised to not hear from Druopitee again, at least not in this timeline.":
            "Als dieses dritte Echo of Druopitee fällt, fühlt sich die Spire plötzlich doppelt so kalt an. Druopitee hat dir erzählt, er habe unendlich viele Versionen von sich in unendlich viele Spires gesetzt, aber in keiner davon dürfte sein Wille noch bei Bewusstsein sein. Du drehst an weiteren Reglern, um mehr Healthy-Mutation in die Welt zu lassen, und findest, dass es nichts Besseres zu tun gibt, als nach weiteren zu suchen. Es würde dich nicht wundern, nie wieder von Druopitee zu hören, zumindest nicht in dieser Zeitlinie.",
        "While you walk through the Spire, you whistle a tune. You haven't yet tired, your motivations zoom. As Fluffy checks for loot in this dark, dusty room, you suddenly see fire and hear a huge boom.":
            "Du schlenderst durch die Spire und pfeifst dir ein Lied, noch bist du nicht müde, die Motivation sprüht. Während Fluffy im staubigen, dunklen Raum nach Beute sieht, siehst du plötzlich Feuer, und ein lauter Knall geschieht.",
        "Against your better judgment, you continue to climb. Heat fills this dungeon, and doubt fills your mind. You feel a great evil that's long been confined, but with reluctance you move on for the good of Trimpkind.":
            "Wider besseres Wissen kletterst du weiter hinauf, Hitze füllt dieses Verlies, und Zweifel steigen auf. Du spürst ein großes Böses, lange eingesperrt zuhauf, doch für das Wohl der Scruffies nimmst du es widerwillig in Kauf.",
        "The fires still grow, but they leave a clear path. Just one direction shown, the thought makes you laugh. Unwisely Druopitee tried to rig this booby trap, but the fire shows the way to go so you thank him for the map.":
            "Die Feuer wachsen weiter, doch ein Weg bleibt frei, nur eine Richtung zeigt sich, du lachst dabei. Unklug hat Druopitee diese Falle gestellt, doch das Feuer zeigt den Weg, und du dankst ihm für die Karte der Welt.",
        "You're close to the top of this large, awful tower. Your fearful thoughts drop, your will is empowered. Luckily you have Fluffy to support you in this hour, you two will never stop until these echoes are devoured.":
            "Du bist fast oben in diesem großen, schrecklichen Turm, deine Ängste verfliegen, dein Wille wird zum Sturm. Zum Glück steht dir Fluffy in dieser Stunde bei, ihr hört nicht auf, bis von den Echos nichts mehr übrig sei.",
        "The presence here is unique from what you felt before. You know it can't speak but it's not done for. An intrusive thought knocks on your mind's back door:<br/><span class='spirePoem'>You are weak. I'll be on the top floor.</span>":
            "Die Präsenz hier ist anders als alles, was du bisher gespürt, du weißt, sie kann nicht sprechen, doch erledigt ist sie nicht, wie es sich gebührt. Ein aufdringlicher Gedanke klopft an die Hintertür deines Geistes, ganz ungeniert:<br/><span class='spirePoem'>Du bist schwach. Ich warte oben, wohin die Treppe führt.</span>",
        "Another thought enters your mind, this time louder than before:<br/><span class='spirePoem'>Your death warrant's signed, soon you'll be no more.<br/>I gave you everything you have, it was no easy chore.<br/>Your Trimps are MINE, prepare for war!</span><br/>Even in death this guy's a dick.":
            "Ein weiterer Gedanke dringt in deinen Kopf, diesmal lauter als zuvor:<br/><span class='spirePoem'>Dein Todesurteil ist unterschrieben, bald bist du nicht mehr hier.<br/>Ich gab dir alles, was du hast, und das war Mühe, glaub es mir.<br/>Deine Scruffies gehören MIR, mach dich bereit zum Krieg mit mir!</span><br/>Selbst tot ist der Typ noch ein Ekel.",
        "As yet another Echo of Druopitee fades into nothingness, you feel something urging you to check underneath a loose stone in the corner of the room. After lifting it up, you find a small notebook with the words \"Global Domination\" written on it. The text all seems to be in Druopitee's handwriting, which you instantly recognize from the books you've found around the planet. The first few pages all discuss Druopitee's success with various creatures here, followed by multiple pages documenting failures at attempts to control the Trimps. The very last page with any writing in it indicates that Druopitee intended to create leaders they'd be more likely to follow, by creating clones of himself mixed with varying amounts of Trimp DNA. Is this where Fluffy came from?!":
            "Während ein weiteres Echo of Druopitee ins Nichts verblasst, drängt dich etwas, unter einem losen Stein in der Ecke des Raums nachzusehen. Als du ihn anhebst, findest du ein kleines Notizbuch mit der Aufschrift ‚Weltherrschaft‘. Der Text scheint komplett in Druopitees Handschrift zu sein, die du sofort aus den Büchern wiedererkennst, die du überall auf dem Planeten gefunden hast. Die ersten Seiten handeln von Druopitees Erfolgen mit verschiedenen Wesen hier, danach dokumentieren mehrere Seiten gescheiterte Versuche, die Scruffies zu kontrollieren. Die letzte beschriebene Seite verrät, dass Druopitee Anführer erschaffen wollte, denen sie eher folgen würden: Klone von sich selbst, gemischt mit unterschiedlich viel Scruffy-DNA. Kommt Fluffy etwa daher?!",
        "You think you can hear a little whimper coming from the walls as you climb the Spire. Druopitee's Echoes are really not doing well.":
            "Während du die Spire hinaufkletterst, glaubst du, ein leises Wimmern aus den Wänden zu hören. Druopitees Echos geht es wirklich nicht gut.",
        "All of the color seems to have drained from the Spire, and all the creatures seem like black and white zombies. You really want to clean this place up and get out.":
            "Alle Farbe scheint aus der Spire gewichen zu sein, und alle Wesen wirken wie schwarz-weiße Zombies. Du willst hier wirklich aufräumen und dann nichts wie raus.",
        "You look out at the lands ahead of you from the top of the Spire.":
            "Von der Spitze der Spire blickst du über das Land vor dir.",
        "You have no idea how to get past the Obsidian. Fluffy seems agitated, like he wants to do something about it but can't quite manage to. Maybe if he was more powerful...":
            "Du hast keine Ahnung, wie du am Obsidian vorbeikommen sollst. Fluffy wirkt aufgeregt, als wolle er etwas dagegen tun, schaffe es aber nicht ganz. Vielleicht, wenn er mächtiger wäre …",
        "Fluffy suggests that you should be able to melt the wall, if you can channel enough power into this Universe. Guess you better get to it !":
            "Fluffy meint, du solltest die Wand schmelzen können, wenn du genug Energie in dieses Universum leitest. Dann mal ran!",
        "It's charred and burned and broken, but you can see the tip of another Spire over the horizon, and the way before you is clear.":
            "Es ist verkohlt, verbrannt und zerbrochen, aber am Horizont siehst du die Spitze einer weiteren Spire, und der Weg vor dir ist frei.",
        "While the Bad Guys here are still heavily mutated and strong, the Spire itself feels like a husk of the earlier ones. The silence makes you shiver but you press on.":
            "Die Gegner hier sind zwar immer noch stark mutiert und kräftig, aber die Spire selbst wirkt wie eine leere Hülle der früheren. Die Stille lässt dich frösteln, aber du machst weiter.",
        "The Echo was so weak that the Spire barely feels different after defeating it. There is an Obsidian wasteland beyond the Spire, and you can't see anything of note out there. Good thing too, because it's grown increasingly more difficult to push the obsidian back.":
            "Das Echo war so schwach, dass sich die Spire nach seinem Fall kaum anders anfühlt. Hinter der Spire liegt eine Obsidianwüste, und dort draußen siehst du nichts Bemerkenswertes. Auch gut so, denn den Obsidian zurückzudrängen, ist immer schwieriger geworden.",
        "With Fluffy's help and a little bit more effort, you could probably push the Obsidian back a few more Zones.":
            "Mit Fluffys Hilfe und etwas mehr Anstrengung könntest du den Obsidian wohl noch ein paar Zonen zurückdrängen.",
        "The path through a few Zones just beyond the Spire is clear, but the not-so-distant Obsidian wall doesn't look like it will ever melt.":
            "Der Weg durch ein paar Zonen gleich hinter der Spire ist frei, aber die nicht allzu ferne Obsidianwand sieht nicht so aus, als würde sie jemals schmelzen.",
        "Scruffy congratulates you on the first step taken on the long journey through this Spire. Your Trimps already feel a little bit stronger!":
            "Scruffy gratuliert dir zum ersten Schritt auf der langen Reise durch diese Spire. Deine Scruffies fühlen sich schon ein kleines bisschen stärker an!",
        "Your Trimps have a simultaneous coughing fit as Spores erupt from that Natural enemy and fill the room. You hear Stuffy attempt evil laughter on the Floor above you, but it honestly humors you more than it does intimidate. This combined with the effect of the Spores causes you to burst out laughing, and you hear an embarrassed Stuffy run further up the Spire.":
            "Deine Scruffies bekommen gleichzeitig einen Hustenanfall, als Sporen aus dem Natural-Gegner hervorbrechen und den Raum füllen. Eine Etage über dir versucht Stuffy ein böses Lachen, aber ehrlich gesagt amüsiert es dich mehr, als dass es dich einschüchtert. Zusammen mit der Wirkung der Sporen musst du laut loslachen, und du hörst, wie ein beschämter Stuffy weiter die Spire hinaufrennt.",
        "Scruffy lets you know that you're one tenth of one tenth of the way to the top. You consider finally giving him that lesson he's been asking for on multiplication of fractions but decide now is probably not the time.":
            "Scruffy teilt dir mit, dass du ein Zehntel eines Zehntels des Weges nach oben geschafft hast. Du überlegst, ihm endlich die Lektion über das Multiplizieren von Brüchen zu geben, um die er dich schon lange bittet, findest aber, dass jetzt wohl nicht der richtige Moment ist.",
        "Another Natural enemy and another stack of the Spores. Your Trimps aren't acting quite as bothered by this one, but they definitely seem to have gotten weaker. Scruffy reminds you that at least there were only two Natural enemies on this Floor and they're both dead. Just gotta get to the next Floor to get out of this cloud, and your Trimps strength should fully return!":
            "Noch ein Natural-Gegner und noch ein Stapel Sporen. Diesmal scheint es deine Scruffies nicht ganz so sehr zu stören, aber schwächer sind sie definitiv geworden. Scruffy erinnert dich daran, dass es auf dieser Etage immerhin nur zwei Natural-Gegner gab und beide tot sind. Du musst nur die nächste Etage erreichen, um aus dieser Wolke herauszukommen, dann sollten deine Scruffies wieder ihre volle Kraft haben!",
        "You're halfway through the first Floor! Stuffy doesn't stand a chance.":
            "Du hast die Hälfte der ersten Etage geschafft! Stuffy hat keine Chance.",
        "About 10 cells ahead, you see a small device emitting some sort of gas. Scruffy lets you know that smashing that will permanently remove this entire Floor from the Universe which sounds like a good thing to you!":
            "Etwa 10 Felder voraus siehst du ein kleines Gerät, das eine Art Gas ausstößt. Scruffy erklärt dir, dass du diese ganze Etage dauerhaft aus dem Universum entfernst, wenn du es zertrümmerst, und das klingt für dich nach einer guten Sache!",
        "You've done it! That's one whole Floor cleared and removed completely from the Universe. Stuffy might be able to run for now, but as long as you can keep chipping away at his Spire, you'll reach him some day, in some timeline. As you begin to start work on the second Floor, you notice a chest containing four Mutated Heirlooms!":
            "Geschafft! Eine ganze Etage ist geräumt und vollständig aus dem Universum entfernt. Stuffy mag vorerst weglaufen können, aber solange du weiter an seiner Spire nagst, erreichst du ihn eines Tages, in irgendeiner Zeitlinie. Als du dich an die zweite Etage machst, bemerkst du eine Truhe mit vier Mutated Heirlooms!",
        "The first Natural enemy is down, but it looks like there's a few more of them on this Floor than the last. Scruffy says that the Natural mutation itself is actually a living entity, and that it's growing as we climb the Spire. Creepy!":
            "Der erste Natural-Gegner ist erledigt, aber auf dieser Etage scheint es ein paar mehr davon zu geben als auf der letzten. Scruffy sagt, die Natural-Mutation selbst sei eigentlich ein lebendes Wesen und wachse, während wir die Spire hinaufklettern. Gruselig!",
        "You hear Stuffy on the Floor above you yelling something about how much he hates pollution, but you don't think there's actually anything natural about this 'Natural' mutation.":
            "Eine Etage über dir hörst du Stuffy etwas darüber brüllen, wie sehr er Umweltverschmutzung hasst, aber du findest, dass an dieser ‚Natural‘-Mutation eigentlich gar nichts natürlich ist.",
        "Stuffy pops out from behind the corpse of the recently destroyed Bad Guy and slaps a Dagger out of the hands of a nearby bewildered Trimp. He asks if you know how much damage was done to the planet to create that Dagger, and you guess not very much. He doesn't seem to have a response and retreats further into the Spire.":
            "Stuffy springt hinter der Leiche des gerade erledigten Gegners hervor und schlägt einem verdutzten Scruffy in der Nähe einen Dolch aus der Hand. Er fragt, ob du weißt, wie viel Schaden dem Planeten zugefügt wurde, um diesen Dolch herzustellen, und du tippst auf nicht besonders viel. Darauf scheint er keine Antwort zu haben und zieht sich tiefer in die Spire zurück.",
        "The worst part of all of this is that you kind of agree with Stuffy's message about not destroying the planet but this Spire seems to be doing a lot more damage than you are, plus he's kind of a jerk.":
            "Das Schlimmste daran ist, dass du Stuffys Botschaft, den Planeten nicht zu zerstören, irgendwie zustimmst, aber diese Spire scheint viel mehr Schaden anzurichten als du, und außerdem ist er ein ziemlicher Idiot.",
        "You've almost reached the end of another Floor, and once again you spot the small, strange, gas-emitting device. You need to destroy it as quickly as possible!":
            "Du hast fast das Ende einer weiteren Etage erreicht, und wieder entdeckst du das kleine, seltsame, gasausstoßende Gerät. Du musst es so schnell wie möglich zerstören!",
        "Another Floor down, another Floor erased from existence. Scruffy points out that you may not remember anything about this Spire after your next Portal, but assures you that he can fill you in whenever you need it. You have gained a lot of knowledge on the Mutations now, and will permanently gain 2x Mutated Seeds.":
            "Noch eine Etage geschafft, noch eine Etage aus der Existenz getilgt. Scruffy weist dich darauf hin, dass du dich nach deinem nächsten Portal vielleicht an nichts aus dieser Spire erinnerst, versichert dir aber, dass er dich jederzeit aufklären kann. Du weißt jetzt viel über die Mutationen und bekommst dauerhaft 2x Mutated Seeds.",
        "The Natural Mutation is still growing! What is it becoming!?":
            "Die Natural-Mutation wächst immer noch! Was wird nur aus ihr!?",
        "Despite all the toxic spore clouds and Mutations, your Trimps are in good spirits. As long as they get to kill Bad Guys, they're usually pretty happy.":
            "Trotz all der giftigen Sporenwolken und Mutationen sind deine Scruffies guter Dinge. Solange sie Gegner erledigen dürfen, sind sie meistens ziemlich glücklich.",
        "You're officially a quarter of the way through the entire Spire. Scruffy tells you that Fluffy would be proud.":
            "Offiziell hast du ein Viertel der gesamten Spire geschafft. Scruffy sagt, Fluffy wäre stolz.",
        "You can't stop thinking about how Scruffy told you the Mutation here was alive, what is it going to grow in to?!":
            "Du musst ständig daran denken, dass Scruffy gesagt hat, die Mutation hier sei lebendig. Was wird aus ihr noch werden?!",
        "You can finally see the gas-emitting device at the end of this Floor! You ask Scruffy what it actually is, and he states that it's a Spire Stabilizer. Apparently the Spires and Mutation spreaders are based on some wild dimension-bending technology that will simply cease existing without the right precautions.":
            "Endlich siehst du das gasausstoßende Gerät am Ende dieser Etage! Du fragst Scruffy, was es eigentlich ist, und er erklärt, dass es ein Spire-Stabilisator ist. Offenbar beruhen die Spires und Mutationsverbreiter auf einer wilden, dimensionsbiegenden Technik, die ohne die richtigen Vorkehrungen einfach aufhört zu existieren.",
        "You've done it! 3 Floors of this wretched place have been scrubbed from existence. Scruffy seems to be growing more powerful with every Floor cleared, and now permanently gains +50% experience!":
            "Geschafft! 3 Etagen dieses elenden Ortes sind aus der Existenz getilgt. Scruffy scheint mit jeder geräumten Etage mächtiger zu werden und bekommt jetzt dauerhaft +50% Exp!",
        "The Mutation here seems to become more plantlike the higher you climb. Scruffy says that's probably what Stuffy was going for.":
            "Die Mutation hier wird pflanzenartiger, je höher du kletterst. Scruffy sagt, darauf hat es Stuffy wahrscheinlich abgesehen.",
        "Stuffy shows up again and tries once more to shame you for the damage you've done to the planet. You just kinda ignore him and he eventually goes away.":
            "Stuffy taucht wieder auf und versucht noch einmal, dir wegen des Schadens, den du dem Planeten zugefügt hast, ein schlechtes Gewissen zu machen. Du ignorierst ihn einfach, und irgendwann geht er wieder.",
        "The spores tickle the inside of your brain!":
            "Die Sporen kitzeln dich innen im Gehirn!",
        "This Floor's Stabilizer is finally within viewing distance! You can't wait to see what goodies await you at the end of this Floor.":
            "Der Stabilisator dieser Etage ist endlich in Sichtweite! Du kannst es kaum erwarten zu sehen, welche Leckerbissen am Ende dieser Etage auf dich warten.",
        "One more Floor, one more Stabilizer. Only one Floor from the halfway point now, you're really making a dent in this Spire! Just as you were escaping the evaporating Floor, you found a strange blue orb and naturally you grabbed it. It didn't seem to react to your touch, but when you tossed it to a nearby Trimp it released an intense burst of energy and caused all your Trimps to look a bit stronger. Your Trimps permanently gained +10% Crit Chance!":
            "Noch eine Etage, noch ein Stabilisator. Nur noch eine Etage bis zur Hälfte, du hinterlässt wirklich eine Delle in dieser Spire! Gerade als du der verdampfenden Etage entkamst, hast du eine seltsame blaue Kugel gefunden und natürlich eingesteckt. Auf deine Berührung schien sie nicht zu reagieren, aber als du sie einem Scruffy in der Nähe zuwarfst, setzte sie einen heftigen Energiestoß frei, und alle deine Scruffies sahen etwas stärker aus. Deine Scruffies haben dauerhaft +10% Krit-Chance erhalten!",
        "The Mutation grows...":
            "Die Mutation wächst …",
        "You ask Scruffy what actually happens if 10 groups of Trimps die here, and he reveals that he actually teleports you out himself. You ask why, and he tells you it's better not to waste time on an impossible task.":
            "Du fragst Scruffy, was eigentlich passiert, wenn hier 10 Gruppen Scruffies sterben, und er verrät dir, dass er dich dann selbst hinausteleportiert. Du fragst, warum, und er sagt, es sei besser, keine Zeit mit einer unmöglichen Aufgabe zu verschwenden.",
        "After some thought about your last conversation with Scruffy, you approach him and ask if he could at least hold off on the teleport if you're like really close to finishing Stuffy off or something. He tells you only a clean kill will suffice.":
            "Nachdem du über dein letztes Gespräch mit Scruffy nachgedacht hast, gehst du zu ihm und fragst, ob er mit dem Teleport nicht wenigstens warten könnte, wenn du Stuffy schon fast erledigt hast oder so. Er sagt, nur ein sauberer Sieg zählt.",
        "You lost all your Trimps! Oh no wait there they are.":
            "Du hast alle deine Scruffies verloren! Ach nein, warte, da sind sie ja.",
        "Just as you expected, there's another Stabilizer on this Floor, and you have located it with your eyeballs.":
            "Wie erwartet gibt es auf dieser Etage einen weiteren Stabilisator, und du hast ihn mit deinen eigenen Augäpfeln geortet.",
        "Scruffy congratulates you on destroying half of Stuffy's Spire! He has a good laugh thinking about how mad Stuffy must be. After waiting an uncomfortable amount of time for him to stop laughing, you ask if he knows anything about this strange device you found at the end of the last Floor. He pushes a button on it, straps it on his arm, and tells you that the bonus Attack, Health and Radon your Trimps were gaining from this Spire are all now doubled!":
            "Scruffy gratuliert dir, dass du die Hälfte von Stuffy's Spire zerstört hast! Bei dem Gedanken, wie wütend Stuffy sein muss, lacht er sich schlapp. Nachdem du unangenehm lange gewartet hast, bis er aufhört zu lachen, fragst du, ob er etwas über das seltsame Gerät weiß, das du am Ende der letzten Etage gefunden hast. Er drückt einen Knopf darauf, schnallt es sich an den Arm und sagt dir, dass sich der Bonus auf Attack, Health und Radon, den deine Scruffies durch diese Spire erhalten, jetzt verdoppelt hat!",
        "As Scruffy predicted, the Mutation continues to grow larger. Is it starting to look a little bit like a tree?":
            "Wie Scruffy vorhergesagt hat, wird die Mutation immer größer. Sieht sie langsam ein bisschen wie ein Baum aus?",
        "You ask Scruffy where Mutations actually came from. He says that it must have been created after he and Fluffy rebelled so he doesn't know much, but that the seeds are extremely energy-dense.":
            "Du fragst Scruffy, woher die Mutationen eigentlich kommen. Er sagt, sie müssen entstanden sein, nachdem Fluffy und er rebelliert haben, deshalb weiß er nicht viel darüber, aber die Samen seien extrem energiereich.",
        "You spot Stuffy hiding behind an incredibly out of place looking bush and decide to just ask him why he's releasing all this Mutation on the planet he claims to love so much. He tells you he's making Nature stronger and that the planet would thank him if it could. Just as you were about to respond, both Stuffy and the bush vanish.":
            "Du entdeckst Stuffy hinter einem Busch, der unglaublich fehl am Platz aussieht, und fragst ihn einfach, warum er all diese Mutation auf dem Planeten freisetzt, den er angeblich so sehr liebt. Er sagt, er mache die Natur stärker, und der Planet würde ihm danken, wenn er könnte. Gerade als du antworten willst, verschwinden Stuffy und der Busch.",
        "Is the Stabilizer on this Floor dancing on 8 legs or are the Spores just starting to get to you? Either way you should probably go break that thing.":
            "Tanzt der Stabilisator dieser Etage auf 8 Beinen, oder setzen dir die Sporen langsam zu? So oder so solltest du das Ding wohl kaputt machen.",
        "As you emerge from the non-existent space of the previous Floor, you take in a deep Spore-free breath and pat yourself on the back. Out of the corner of your eye you notice a small yellow shard, and touching it fills you with ancient knowledge allowing you to gain an extra 20% Nullifium when recycling Heirlooms!":
            "Als du aus dem nicht mehr existierenden Raum der vorigen Etage auftauchst, holst du tief und sporenfrei Luft und klopfst dir selbst auf die Schulter. Aus dem Augenwinkel bemerkst du eine kleine gelbe Scherbe, und als du sie berührst, erfüllt dich uraltes Wissen: Beim Recyceln von Heirlooms bekommst du jetzt 20% mehr Nullifium!",
        "Ok that Mutation is definitely a tree. A big scary tree!":
            "Okay, diese Mutation ist definitiv ein Baum. Ein großer, gruseliger Baum!",
        "Scruffy seems to be growing tired of making notes of everything that has happened in this Spire.":
            "Scruffy wird es offenbar langsam leid, alles zu notieren, was in dieser Spire passiert ist.",
        "Stuffy comes by once again but you can't really understand what he's saying. You're not sure if it's the spores or if he's just messing with you.":
            "Stuffy kommt wieder einmal vorbei, aber du verstehst nicht recht, was er sagt. Du weißt nicht, ob es an den Sporen liegt oder ob er dich nur veräppelt.",
        "Once again you spot a Stabilizer! You really want to clear it fast, the spores are not very enjoyable.":
            "Wieder entdeckst du einen Stabilisator! Du willst ihn wirklich schnell erledigen, die Sporen sind nicht besonders angenehm.",
        "As you finish up the Floor and the Floor drains away, you take a look at your Trimps and realize they're pretty great. That's seven whole floors and one mad Stuffy, and now Scruffy earns another 50% XP!":
            "Als du die Etage abschließt und sie verschwindet, betrachtest du deine Scruffies und merkst, dass sie ziemlich großartig sind. Das macht sieben ganze Etagen und einen wütenden Stuffy, und jetzt bekommt Scruffy weitere 50% Exp!",
        "One of the Mutated cells here looks different! You ask Scruffy about it and he tells you that the orange ones have a much higher concentration of Spores, and will release 10x the normal amount of Spores when attacked and killed. You're not liking the sound of that...":
            "Eines der mutierten Felder hier sieht anders aus! Du fragst Scruffy danach, und er erklärt dir, dass die orangefarbenen eine viel höhere Sporenkonzentration haben und beim Angreifen und Erledigen 10x so viele Sporen freisetzen wie normal. Das klingt gar nicht gut …",
        "You've made it three quarters of the way through the Spire! This evil structure is now a small fragment of what it once was, thanks to you. Scruffy offers you a small, strange berry as congratulations.":
            "Du hast drei Viertel der Spire geschafft! Dieses böse Bauwerk ist dank dir nur noch ein kleines Bruchstück dessen, was es einmal war. Scruffy reicht dir zur Feier eine kleine, seltsame Beere.",
        "Stuffy stops by again and asks you really nicely to just leave. He says he won't mess with you anymore, but that he can't stand to let Druopitee down. You tell him you'll leave if he destroys the rest of the Spire, but he just makes a weird noise and runs off.":
            "Stuffy kommt wieder vorbei und bittet dich sehr nett, doch einfach zu gehen. Er sagt, er werde dich nicht mehr ärgern, könne es aber nicht ertragen, Druopitee zu enttäuschen. Du sagst ihm, dass du gehst, wenn er den Rest der Spire zerstört, aber er macht nur ein komisches Geräusch und rennt davon.",
        "You know the deal, another Stabilizer spotted for your Spire-Destroying pleasure!":
            "Du kennst das schon: Noch ein Stabilisator gesichtet, ganz zu deinem Spire-Zerstörungsvergnügen!",
        "That's eight Floors down, two to go! You found another strange blue orb which you toss directly to a Trimp and show no surprise when they gain another +15% Crit Chance! Scruffy points forward, you nod your head, and continue on.":
            "Acht Etagen geschafft, zwei fehlen noch! Du hast noch eine seltsame blaue Kugel gefunden, wirfst sie direkt einem Scruffy zu und bist kein bisschen überrascht, als deine Scruffies weitere +15% Krit-Chance erhalten! Scruffy zeigt nach vorne, du nickst und gehst weiter.",
        "The Mutation continues to grow and organize. You let out a deep sigh thinking about how many Spores will be in the air at the end of this Floor.":
            "Die Mutation wächst weiter und ordnet sich. Du seufzt tief bei dem Gedanken, wie viele Sporen am Ende dieser Etage in der Luft sein werden.",
        "Stuffy tried to take a Trimp hostage in order to force you to leave, but he dropped the Trimp and it ran back like nothing happened.":
            "Stuffy hat versucht, einen Scruffy als Geisel zu nehmen, um dich zum Gehen zu zwingen, aber er hat ihn fallen lassen, und der Scruffy ist zurückgerannt, als wäre nichts gewesen.",
        "Stuffy's making some odd noises up ahead, it seems like you've thoroughly frightened him.":
            "Stuffy macht da vorne seltsame Geräusche. Anscheinend hast du ihm einen ordentlichen Schrecken eingejagt.",
        "Is that another Stabilizer down there? Don't mind if you do.":
            "Ist da unten etwa noch ein Stabilisator? Da sagst du nicht Nein.",
        "You've actually done it! You've made it to the final Floor! Scruffy tells you that this Floor was stabilized by Druopitee himself and cannot be permanently removed from all timelines, but that you can certainly remove it and Stuffy from this timeline. Now that you can think properly without the Spores of the previous Floor, you realize there's some new knowledge in your head that will allow you to gain 2x more Seeds!":
            "Du hast es tatsächlich geschafft! Du bist auf der letzten Etage angekommen! Scruffy erklärt dir, dass Druopitee diese Etage selbst stabilisiert hat und sie nicht dauerhaft aus allen Zeitlinien entfernt werden kann, aber aus dieser Zeitlinie kannst du sie und Stuffy auf jeden Fall entfernen. Jetzt, da du ohne die Sporen der vorigen Etage wieder klar denken kannst, merkst du, dass neues Wissen in deinem Kopf steckt, mit dem du 2x mehr Seeds bekommst!",
        "You can sense Stuffy at the end of this Floor. The little fella has nowhere else to run! It's time to finish this.":
            "Du spürst Stuffy am Ende dieser Etage. Der kleine Kerl kann nirgendwohin mehr fliehen! Zeit, das zu Ende zu bringen.",
        "A Trimp walks up to you and offers you a small stick he found as a good luck charm. With the power of this stick, you basically can't lose now.":
            "Ein Scruffy kommt zu dir und schenkt dir einen kleinen Stock, den er gefunden hat, als Glücksbringer. Mit der Macht dieses Stocks kannst du jetzt praktisch nicht mehr verlieren.",
        "You're so close you can almost taste the impending victory. Or maybe that's just all the spores in the air.":
            "Du bist so nah dran, dass du den bevorstehenden Sieg fast schmecken kannst. Oder das sind nur die vielen Sporen in der Luft.",
        "Just as Scruffy predicted, there's no Stabilizer at the end of this Floor. But there is a Stuffy, and destroying him will be good enough for you.":
            "Wie Scruffy vorhergesagt hat, gibt es am Ende dieser Etage keinen Stabilisator. Aber es gibt einen Stuffy, und ihn zu vernichten, reicht dir völlig.",
        "Stuffy lets out a shriek as your Trimps finish him off. You smash the Mutation spreader into a thousand pieces, and the air begins to clear. However you still see a large amount of Mutation ahead of you in the World, and it becomes apparent that you'll be needing to pay a visit to Buffy next. Scruffy lets you know that you've done an amazing thing for the timeline, and that the ruins of the Spire are now acting as a beacon increasing your Trimps Attack, Health, and your Radon gain by 10x until you Portal. You've done something amazing here, and with a massive sense of accomplishment you continue on to the next one.":
            "Stuffy stößt einen Schrei aus, als deine Scruffies ihm den Rest geben. Du zertrümmerst den Mutationsverbreiter in tausend Stücke, und die Luft beginnt sich zu klären. Doch vor dir in der Welt siehst du noch jede Menge Mutation, und es wird klar, dass du als Nächstes Buffy einen Besuch abstatten musst. Scruffy sagt dir, dass du für die Zeitlinie etwas Großartiges getan hast und dass die Ruinen der Spire jetzt wie ein Leuchtfeuer wirken: Bis zu deinem nächsten Portal steigen Attack und Health deiner Scruffies sowie dein Radon-Ertrag auf das 10-Fache. Du hast hier etwas Großartiges vollbracht, und mit einem gewaltigen Erfolgsgefühl ziehst du weiter zur nächsten.",
        "Gah! They're all empty!":
            "Argh! Die sind ja alle leer!",
        "Out of the corner of your eye, you notice a creature who doesn't seem like he belongs. You walk up closer and notice that it's Fluffy! You turn around expecting to see your other Fluffy, but there is only one. You turn back as he waves at you in recognition, you feel a bit lightheaded, but you've had weirder things happen on this planet. You decide to keep moving up the Spire with your new old friend.":
            "Aus dem Augenwinkel bemerkst du ein Wesen, das nicht hierherzugehören scheint. Du gehst näher heran und siehst, dass es Fluffy ist! Du drehst dich um und erwartest, deinen anderen Fluffy zu sehen, aber es gibt nur einen. Als du dich wieder umdrehst, winkt er dir erkennend zu. Dir wird ein bisschen schwindlig, aber auf diesem Planeten hast du schon Seltsameres erlebt. Du beschließt, mit deinem neuen alten Freund weiter die Spire hinaufzusteigen.",
        "Out of the corner of your eye, you notice a creature who doesn't seem like he belongs. You walk up closer and notice that it's a Trimp! Only this Trimp is purple instead of blue, obviously a result of some experiments by Druopitee. You let him know not to worry, and that you'll keep him safe. You name him Fluffy, and vow to never let any harm come to him. <b>Gained 1 Trimp!</b>":
            "Aus dem Augenwinkel bemerkst du ein Wesen, das nicht hierherzugehören scheint. Du gehst näher heran und siehst, dass es ein Scruffy ist! Nur ist dieser Scruffy lila statt blau, offensichtlich das Ergebnis irgendwelcher Experimente von Druopitee. Du sagst ihm, dass er keine Angst haben muss und dass du ihn beschützt. Du nennst ihn Fluffy und schwörst, dass ihm nie etwas zustoßen wird. <b>1 Scruffy erhalten!</b>",
        "You search around for some more resources but find nothing. Lame.":
            "Du suchst nach weiteren Ressourcen, findest aber nichts. Öde.",
        "You find a <b>brand new Spire Core</b>!":
            "Du findest einen <b>brandneuen Spire Core</b>!",
        "For your first time killing this Echo in any timeline, you have permanently added another 5% to your Liquification bonus, increased your Dark Essence gains by 4x, and earned <b>20 bones!</b>":
            "Weil du dieses Echo zum ersten Mal in irgendeiner Zeitlinie erledigt hast, steigt dein Liquification-Bonus dauerhaft um weitere 5%, deine Dark-Essence-Erträge steigen auf das 4-Fache, und du bekommst <b>20 Knochen!</b>",
        "You have also unlocked the <b>Capable</b> perk and can carry an additional Heirloom!":
            "Außerdem hast du den Perk <b>Capable</b> freigeschaltet und kannst ein zusätzliches Heirloom tragen!",
        "You have also unlocked the <b>Cunning</b> perk and can carry an additional Heirloom!":
            "Außerdem hast du den Perk <b>Cunning</b> freigeschaltet und kannst ein zusätzliches Heirloom tragen!",
        "You have also unlocked the <b>Curious</b> perk!":
            "Außerdem hast du den Perk <b>Curious</b> freigeschaltet!",
        "You have also unlocked the <b>Classy</b> perk!<b>":
            "Außerdem hast du den Perk <b>Classy</b> freigeschaltet!<b>",
        "The voice booms again, and sounds as if it is coming from the walls themselves.<br/><br/><span class='spirePoem'>It has been forever, yet now we meet,<br/>I'm not surprised you don't remember me.<br/>I believe it is I who you currently seek,<br/>Lifetimes ago I was Druopitee.</span>":
            "Wieder dröhnt die Stimme, und es klingt, als käme sie aus den Wänden selbst.<br/><br/><span class='spirePoem'>Eine Ewigkeit ist's her, doch nun treffen wir uns hie,<br/>Dass du dich nicht erinnerst, überrascht mich nie.<br/>Ich glaube, mich suchst du, mehr als irgendwen je,<br/>Vor vielen Leben war ich Druopitee.</span>",
        "<br/>You're glad you remembered his name correctly! You feel tougher as memories begin to flood back, and <b>unlocked Toughness II</b>!":
            "<br/>Du bist froh, dass du dir seinen Namen richtig gemerkt hast! Während die Erinnerungen zurückströmen, fühlst du dich zäher und <b>hast Toughness II freigeschaltet</b>!",
        "<span class='spirePoem'>On our planet you and I studied time,<br/>We realized Warp Speed could affect that line.<br/>I took our work in a ship of my own design,<br/>To test the effects of our new paradigm.</span><br/>Oh yeah. That's where you knew him from! Wait doesn't he owe you some money? You feel fair taking a vial of <b>40 Nullifium</b> from a research table.":
            "<span class='spirePoem'>Auf unserem Planeten erforschten wir die Zeit,<br/>Und sahen: Warp-Tempo verbiegt sie weit.<br/>Ich nahm unsere Arbeit in ein Schiff, selbst entworfen, bereit,<br/>Um zu prüfen, was unsere neue Lehre verleiht.</span><br/>Ach ja. Daher kanntest du ihn! Moment, schuldet er dir nicht noch Geld? Ganz fair nimmst du dir eine Phiole mit <b>40 Nullifium</b> von einem Forschungstisch.",
        "<span class='spirePoem'>My tests made other dimensions appear,<br/>I found this planet in one and flew here.<br/>There were hordes of enemies, if that wasn't clear,<br/>The finding was huge but the threat severe.</span><br/>Ah, so you're in a different dimension than your friends and family, comforting.":
            "<span class='spirePoem'>Meine Tests ließen andere Dimensionen erscheinen,<br/>In einer fand ich diesen Planeten und flog her zu den Seinen.<br/>Hier gab es Horden von Feinden, falls das unklar mag scheinen,<br/>Der Fund war gewaltig, die Gefahr nicht zu verneinen.</span><br/>Ah, du bist also in einer anderen Dimension als deine Freunde und Familie. Wie beruhigend.",
        "Your desire to go home some day causes strength to flow through you, and you <b>unlocked Power II</b>!":
            "Dein Wunsch, eines Tages nach Hause zu kommen, lässt Kraft durch dich strömen, und du <b>hast Power II freigeschaltet</b>!",
        "<span class='spirePoem'>To stay safe, I built many large towers.<br/>I'd climb up, and I'd peer out for hours.<br/>I searched for lifetimes, my mind became devoured,<br/>then one day I found a way to gain power.</span><br/>Dammit Druopitee. This is all going to end up being his fault, isn't it?":
            "<span class='spirePoem'>Zum Schutz baute ich Türme, groß und schwer.<br/>Ich stieg hinauf und spähte stundenlang umher.<br/>Ich suchte Leben lang, mein Geist verzehrt und leer,<br/>bis ich eines Tages fand, wie ich Macht gewinne, mehr und mehr.</span><br/>Verdammt, Druopitee. Am Ende ist das alles seine Schuld, oder?",
        "You look for something to steal to try and even the playing field, but can't find anything. Oh well.":
            "Du suchst nach etwas zum Mitgehenlassen, um die Rechnung auszugleichen, findest aber nichts. Na ja.",
        "<span class='spirePoem'>After many lifetimes of observation,<br/>I had finally found my salvation.<br/>An airborne chemical to cause great mutation,<br/>the Corruption was my new creation.</span><br/>Yup, totally his fault.":
            "<span class='spirePoem'>Nach Leben voller Beobachtung und Spekulation,<br/>Fand ich endlich meine Erlösung, meine Mission.<br/>Ein Stoff in der Luft für gewaltige Mutation,<br/>Die Corruption war meine neue Kreation.</span><br/>Jep, eindeutig seine Schuld.",
        "Your desire to stop him is so strong that you've <b>unlocked Motivation II</b>!":
            "Dein Wunsch, ihn aufzuhalten, ist so stark, dass du <b>Motivation II freigeschaltet hast</b>!",
        "<span class='spirePoem'>I pumped Corruption up from my spires,<br/>I watched as it spread outward like wildfires.<br/>They now bowed to me, their brains freshly rewired,<br/>I had almost all that I desired.</span><br/>You feel like anyone willing to pump something called 'Corruption' into a planet's atmosphere probably qualifies as a supervillain. You feel no remorse taking another vial filled with <b>60 Nullifium</b>!":
            "<span class='spirePoem'>Ich pumpte Corruption aus meinen Spires empor,<br/>Sah, wie sie sich ausbreitete wie ein Lauffeuer, nie zuvor.<br/>Nun beugten sie sich mir, ihr Hirn neu verdrahtet, im Chor,<br/>Fast alles hatte ich, was ich mir erkor.</span><br/>Wer bereit ist, etwas namens ‚Corruption‘ in die Atmosphäre eines Planeten zu pumpen, ist wohl ein waschechter Superschurke. Ohne Reue nimmst du dir noch eine Phiole mit <b>60 Nullifium</b>!",
        "<span class='spirePoem'>But Trimps, who in numbers are tough as stone,<br/>weren't changed and I couldn't control them alone.<br/>So I got in my ship and I went to our home,<br/>I brought you here to the native Trimp Zones.</span><br/>You don't remember that, but are pretty sure you weren't OK with it. Kidnapping definitely justifies taking this research <b>Heirloom</b> you just found.":
            "<span class='spirePoem'>Doch die Scruffies, in Massen hart wie Stein,<br/>Blieben unverändert, ich bekam sie allein nicht klein.<br/>Also stieg ich in mein Schiff und flog zu uns heim,<br/>Und brachte dich her ins Scruffy-Land hinein.</span><br/>Daran erinnerst du dich nicht, aber du bist ziemlich sicher, dass du nicht einverstanden warst. Eine Entführung rechtfertigt es allemal, dieses Forschungs-<b>Heirloom</b> mitzunehmen, das du gerade gefunden hast.",
        "<span class='spirePoem'>You disliked my plan and had to be forced,<br/>so I wiped your mind and plotted your course.<br/>I came up with plans for equipment and resorts,<br/>I wrote all I knew and left you reports.</span><br/>Oh HE wrote those? Now that you think about it, you can see a lot of ways the designs could be improved":
            "<span class='spirePoem'>Mein Plan gefiel dir nicht, ich musste dich zwingen,<br/>Drum löschte ich dein Gedächtnis, um dich auf Kurs zu bringen.<br/>Ich entwarf Ausrüstung und Resorts, damit sie gelingen,<br/>Schrieb alles nieder und ließ dir Berichte, die von mir singen.</span><br/>Ach, DIE hat ER geschrieben? Wenn du jetzt darüber nachdenkst, fallen dir viele Möglichkeiten ein, wie man die Entwürfe verbessern könnte",
        ", and <b>unlocked Carpentry II</b>!":
            ", und du <b>hast Carpentry II freigeschaltet</b>!",
        "<span class='spirePoem'>Your Trimps grew strong while I watched and waited,<br/>Their loyalty can not be debated.<br/>You knew not of my plan, yet participated,<br/>Now bow to me or be terminated.</span><br/>Yeah you don't really feel too much like bowing and probably won't be doing that.":
            "<span class='spirePoem'>Deine Scruffies wurden stark, ich sah zu und ließ sie gewähren,<br/>An ihrer Treue gibt es nichts zu erklären.<br/>Du kanntest meinen Plan nicht, halfst ihn aber zu nähren,<br/>Nun knie vor mir, oder ich werde dich verzehren.</span><br/>Tja, nach Knien ist dir nicht wirklich zumute, und das wirst du wohl auch nicht tun.",
        "Druopitee collapses to the floor. You were hoping he'd be a little more sane, but whatever. You shut down the corruption device and hope the planet will repair itself soon, then you rummage through his stuff and find keys, surely for the ship!":
            "Druopitee bricht zusammen. Du hattest gehofft, er wäre etwas vernünftiger, aber egal. Du schaltest das Corruption-Gerät ab und hoffst, dass sich der Planet bald erholt, dann durchwühlst du seine Sachen und findest Schlüssel, bestimmt für das Schiff!",
        "Your skills at salvaging things from this Spire have helped you <b>unlock Looting II</b>.":
            "Dein Geschick beim Plündern dieser Spire hat dir geholfen, <b>Looting II freizuschalten</b>.",
        "<br/><br/>You notice a small timeworn chest in the back of the room, where Druopitee had been storing the Skeletimp bones that he had collected over many timelines. You open it and find <b>20 Perfect Skeletimp Bones!</b> You can tell though that these bones won't be here next time. The Spire's power grants you a permanent 4x bonus to all Dark Essence you collect, you can carry an additional Heirloom back through the Portal, and your Portal has also modified itself to now Liquify Zones equal to 5% of your highest Zone reached. You're not quite sure what a liquify is, but you're excited to find out!":
            "<br/><br/>Hinten im Raum bemerkst du eine kleine, abgenutzte Truhe, in der Druopitee die Rattlekin-Knochen aufbewahrt hat, die er über viele Zeitlinien gesammelt hat. Du öffnest sie und findest <b>20 perfekte Rattlekin-Knochen!</b> Du ahnst aber, dass diese Knochen beim nächsten Mal nicht mehr hier sein werden. Die Macht der Spire gewährt dir dauerhaft einen 4-fachen Bonus auf alle Dark Essence, die du sammelst, du kannst ein zusätzliches Heirloom durch das Portal mitnehmen, und dein Portal hat sich so verändert, dass es jetzt Zonen bis 5% deiner höchsten erreichten Zone verflüssigt (Liquify). Du weißt nicht genau, was Verflüssigen ist, aber du bist gespannt darauf!",
        "<br/><br/><b>You've also found a large, pulsing core that seems to be powering the Spire. You try to carefully remove it but instead smash it into 20 still-humming pieces! You give the pieces to your Scientists, who name the magical new material \"Spirestones\" and use them to begin construction on your own Spire!</b>":
            "<br/><br/><b>Außerdem hast du einen großen, pulsierenden Kern gefunden, der die Spire anzutreiben scheint. Du versuchst, ihn vorsichtig auszubauen, zertrümmerst ihn aber in 20 noch summende Stücke! Du gibst die Stücke deinen Forschern, die das magische neue Material ‚Spirestones‘ nennen und damit beginnen, deine eigene Spire zu bauen!</b>",
        "<br/><br/><b>You were able to properly remove the Core this time, and have found a Basic Spire Core Heirloom!</b>":
            "<br/><br/><b>Diesmal konntest du den Kern richtig ausbauen und hast ein Basic Spire Core Heirloom gefunden!</b>",
        "<br/><br/>You've helped the Trimps establish a legendary population and economy, and have brought down the man responsible for the chaos in this world. You could leave now and the Universe will forever be better because you existed. Trimps will erect statues of you as long as their civilization survives. But you know there are still other spires out there, pumping Corruption into the planet. Maybe the statues would be bigger if you stayed and helped out?":
            "<br/><br/>Du hast den Scruffies zu einer legendären Bevölkerung und Wirtschaft verholfen und den Mann zu Fall gebracht, der für das Chaos in dieser Welt verantwortlich ist. Du könntest jetzt gehen, und das Universum wäre für immer besser, weil es dich gab. Die Scruffies werden dir Statuen errichten, solange ihre Zivilisation besteht. Aber du weißt, dass es dort draußen noch andere Spires gibt, die Corruption in den Planeten pumpen. Vielleicht würden die Statuen größer, wenn du bleibst und hilfst?"
    };
    // Reward and status sentences with numbers (main.js), sticky so the composer can try them at any position.
    const rewards = [
        [["You're suddenly standing outside of the Spire with a feeling that it's best to move on for now. Scruffy seems confident that you'll get it next time! (You made it to Cell ", D, ' on Floor ', D, ')'],
            (_, cell, floor) => 'Du stehst plötzlich vor der Spire und hast das Gefühl, dass du für den Moment besser weiterziehst. Scruffy ist zuversichtlich, dass du es nächstes Mal schaffst! (Du bist bis Feld ' + cell + ' auf Etage ' + floor + ' gekommen)'],
        [["You're not yet ready. Maybe you'll be of use in the next lifetime (You made it to cell ", D, ').'],
            (_, cell) => 'Du bist noch nicht bereit. Vielleicht bist du im nächsten Leben von Nutzen (Du bist bis Feld ' + cell + ' gekommen).'],
        [[D, {re: ' groups? '}, 'of Trimps ', {re: '(?:has|have)'}, ' perished in the Spire.'],
            (_, n) => n + (n === '1' ? ' Gruppe Scruffies ist' : ' Gruppen Scruffies sind') + ' in der Spire umgekommen.'],
        [['You think you can see the tip of another Spire over the Horizon, but the impenetrable wall of Obsidian ', D, {re: ' Zones?'}, ' away makes getting there impossible right now.'],
            (_, n) => 'Du glaubst, am Horizont die Spitze einer weiteren Spire zu sehen, aber die undurchdringliche Obsidianwand ' + n + (n === '1' ? ' Zone' : ' Zonen') + ' entfernt macht es gerade unmöglich, dorthin zu kommen.'],
        [['You found ', N, ' Nullifium!'], (_, n) => 'Du hast ' + n + ' Nullifium gefunden!'],
        [['You help yourself to a container filled with ', N, " Helium, and figure he'll owe you a lot more than that once you hear some more."],
            (_, n) => 'Du bedienst dich an einem Behälter voller ' + n + ' Helium und rechnest damit, dass er dir noch viel mehr schuldet, sobald du mehr hörst.'],
        [['You help yourself to a container filled with ', N, ' Helium!'], (_, n) => 'Du bedienst dich an einem Behälter voller ' + n + ' Helium!'],
        [['Fluffy suddenly drops to all of his extremities and begins closely inspecting the walls. After a few moments he chooses a location and smashes a hole in it, then pulls a small book out of said hole. Without even opening it up, he eats the book and gains ', N, ' experience! What a magnificent creature.'],
            (_, n) => 'Plötzlich lässt sich Fluffy auf alle viere fallen und untersucht die Wände ganz genau. Nach ein paar Augenblicken sucht er sich eine Stelle aus, schlägt ein Loch hinein und zieht ein kleines Buch aus besagtem Loch. Ohne es auch nur aufzuschlagen, frisst er das Buch und erhält ' + n + ' Exp! Was für ein prächtiges Geschöpf.'],
        [['You found a Z', D, ' Heirloom!'], (_, z) => 'Du hast ein Z' + z + '-Heirloom gefunden!'],
        [['You found ', N, ' of each type of Nature Token!'], (_, n) => 'Du hast ' + n + ' Nature Tokens jeder Sorte gefunden!'],
        [["You figure you'll help yourself to another container filled with ", N, ' Helium!'], (_, n) => 'Du bedienst dich gleich an einem weiteren Behälter voller ' + n + ' Helium!'],
        [['You find a large stockpile of <b>', N, ' Helium</b> and <b>a brand new Spire Core</b>!'],
            (_, n) => 'Du findest einen großen Vorrat von <b>' + n + ' Helium</b> und <b>einen brandneuen Spire Core</b>!'],
        [["<br/><span class='fullDarkEssence'>At the top of this Spire, you found a gigantic, pitch-black cache with ", N, ' Dark Essence inside, just enough to complete your entire collection!</span><br/>'],
            (_, n) => "<br/><span class='fullDarkEssence'>Oben in dieser Spire hast du ein gigantisches, pechschwarzes Versteck mit " + n + ' Dark Essence gefunden, genau genug, um deine ganze Sammlung zu vervollständigen!</span><br/>'],
        [['You did however find ', N, ' more Helium just sitting around, which you feel no qualms about taking.'],
            (_, n) => 'Immerhin hast du noch ' + n + ' Helium gefunden, das einfach herumlag, und nimmst es ohne Skrupel mit.'],
        [['You also find a massive stockpile of <b>', N, ' Helium</b>.'], (_, n) => 'Außerdem findest du einen gewaltigen Vorrat von <b>' + n + ' Helium</b>.'],
        // Helium of the other Spire cells (Loot)
        [["As you're leaving, you find ", N, ' helium!'], (_, n) => 'Beim Hinausgehen findest du ' + n + ' Helium!'],
        [['You found ', N, ' helium!'], (_, n) => 'Du hast ' + n + ' Helium gefunden!']
    ].map(([parts, replace]) => [build(parts, 'y'), replace]);
    const pieces = Object.entries(spire).map(([english, german]) => [brand(english).trim(), german]).sort((a, b) => b[0].length - a[0].length);
    const filler = /\s+|<\/?[a-z][^>]*>|[.,!?:;]+/y;
    // Reads the branded line piece by piece: known parts, rewards with numbers, and between them only whitespace, tags and
    // punctuation, which stay as they are. Returns null as soon as anything is unknown.
    function compose(line) {
        let at = 0, out = '', known = 0;
        read: while (at < line.length) {
            for (const [english, german] of pieces) if (line.startsWith(english, at)) { out += german; at += english.length; known++; continue read; }
            for (const [pattern, replace] of rewards) {
                pattern.lastIndex = at;
                const match = pattern.exec(line);
                if (match) { out += replace(...match); at += match[0].length; known++; continue read; }
            }
            filler.lastIndex = at;
            const rest = filler.exec(line);
            if (!rest) return null;
            out += rest[0]; at += rest[0].length;
        }
        return known ? out : null;
    }
    // The composer answers every line behind this probe (German or null), so it is registered as the last log group.
    const spireProbe = /Spire|Nullifium|Helium|helium|Heirloom|Nature Token|Druopitee|perished|Fluffy|spirePoem|not yet ready/;
    const catalog = {strings: {...zones, ...spire}, zones, zonePatterns, spire, rewards, compose};
    if (typeof MobileI18nGame !== 'undefined') {
        MobileI18nGame.registerLog('de', {strings: catalog.strings, patterns: zonePatterns, probe: zoneProbe});
        MobileI18nGame.registerLog('de', {patterns: [[/^[\s\S]+$/, line => compose(line)]], probe: spireProbe});
    }
    return catalog;
})();
if (typeof module !== 'undefined') module.exports = MobileI18nDeStory;
